# CELL 2: Prepare UNSW-NB15 for Transformer training

import numpy as np
import pandas as pd
import torch

from sklearn.impute import SimpleImputer
from sklearn.preprocessing import StandardScaler, OrdinalEncoder, LabelEncoder

SEED = 42
np.random.seed(SEED)
torch.manual_seed(SEED)

# Copy data so the original dataframes remain unchanged
train = train_df.copy()
test = test_df.copy()

# Clean target labels
train["attack_cat"] = train["attack_cat"].astype("string").str.strip()
test["attack_cat"] = test["attack_cat"].astype("string").str.strip()

train = train.dropna(subset=["attack_cat"]).copy()
test = test.dropna(subset=["attack_cat"]).copy()

# Remove identifiers and labels from model inputs
excluded_cols = ["id", "label", "attack_cat"]
feature_cols = [c for c in train.columns if c not in excluded_cols]

# Identify numeric and categorical features from training data
cat_cols = train[feature_cols].select_dtypes(
    include=["object", "category", "string", "bool"]
).columns.tolist()

num_cols = [c for c in feature_cols if c not in cat_cols]

print("Numeric features:", len(num_cols))
print("Categorical features:", cat_cols)

# Numeric preprocessing: fit using training data only
Xtr_num_df = train[num_cols].apply(pd.to_numeric, errors="coerce")
Xte_num_df = test[num_cols].apply(pd.to_numeric, errors="coerce")

Xtr_num_df = Xtr_num_df.replace([np.inf, -np.inf], np.nan)
Xte_num_df = Xte_num_df.replace([np.inf, -np.inf], np.nan)

imputer = SimpleImputer(strategy="median")
Xtr_num = imputer.fit_transform(Xtr_num_df)
Xte_num = imputer.transform(Xte_num_df)

scaler = StandardScaler()
X_train_num = scaler.fit_transform(Xtr_num).astype(np.float32)
X_test_num = scaler.transform(Xte_num).astype(np.float32)

# Categorical preprocessing: unknown test categories get code -1
Xtr_cat_df = train[cat_cols].fillna("MISSING").astype(str)
Xte_cat_df = test[cat_cols].fillna("MISSING").astype(str)

cat_encoder = OrdinalEncoder(
    handle_unknown="use_encoded_value",
    unknown_value=-1
)

X_train_cat = cat_encoder.fit_transform(Xtr_cat_df).astype(np.int64) + 1
X_test_cat = cat_encoder.transform(Xte_cat_df).astype(np.int64) + 1

# Reserve index 0 for unseen categories
X_train_cat = np.maximum(X_train_cat, 0)
X_test_cat = np.maximum(X_test_cat, 0)

# Encode attack categories using training labels only
target_encoder = LabelEncoder()
y_train = target_encoder.fit_transform(train["attack_cat"].astype(str))

unseen = sorted(
    set(test["attack_cat"].astype(str))
    - set(target_encoder.classes_)
)

if unseen:
    raise ValueError(
        f"Test set contains attack categories absent from training: {unseen}. "
        "Inspect these categories before proceeding."
    )

y_test = target_encoder.transform(test["attack_cat"].astype(str))

# Embedding vocabulary sizes for categorical columns
CAT_CARDINALITIES = [
    len(categories) + 1 for categories in cat_encoder.categories_
]

NUM_FEATURES = X_train_num.shape[1]
NUM_CLASSES = len(target_encoder.classes_)
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

print("\n========== PREPROCESSING COMPLETE ==========")
print("Training numeric:", X_train_num.shape)
print("Testing numeric :", X_test_num.shape)
print("Training categorical:", X_train_cat.shape)
print("Testing categorical :", X_test_cat.shape)
print("Attack classes:", list(target_encoder.classes_))
print("Number of classes:", NUM_CLASSES)
print("Device:", DEVICE)

import torch
import time

DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

