import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import confusion_matrix, classification_report, ConfusionMatrixDisplay

model_names = ["FT-Transformer", "SAINT", "TabTransformer"]
class_names = list(target_encoder.classes_)
labels = np.arange(len(class_names))

for model_name in model_names:
    if model_name not in test_probabilities:
        print(f"Predictions not found for {model_name}.")
        continue

    probabilities = np.asarray(test_probabilities[model_name])
    predictions = np.argmax(probabilities, axis=1)

    # Confusion matrix: actual counts
    cm = confusion_matrix(y_test, predictions, labels=labels)

    # Confusion matrix: row-wise percentages
    row_totals = cm.sum(axis=1, keepdims=True)
    cm_percent = np.divide(
        cm * 100,
        row_totals,
        out=np.zeros_like(cm, dtype=float),
        where=row_totals != 0
    )

    fig, ax = plt.subplots(figsize=(12, 10))
    display = ConfusionMatrixDisplay(
        confusion_matrix=cm_percent,
        display_labels=class_names
    )
    display.plot(
        ax=ax,
        cmap="Blues",
        values_format=".1f",
        colorbar=True
    )

    ax.set_title(f"{model_name} — Confusion Matrix (%)")
    ax.set_xlabel("Predicted class")
    ax.set_ylabel("Actual class")
    plt.xticks(rotation=45, ha="right")
    plt.tight_layout()

    filename = model_name.lower().replace("-", "_").replace(" ", "_")
    plt.savefig(f"{filename}_confusion_matrix_percent.png",
                dpi=300, bbox_inches="tight")
    plt.show()

    print(f"\n{model_name} — Per-class results")
    print(classification_report(
        y_test,
        predictions,
        labels=labels,
        target_names=class_names,
        digits=4,
        zero_division=0
    ))

# ============================================================
# AI-IDS: ROC CURVES, PRECISION-RECALL CURVES, AND AUC TABLE
# Models: FT-Transformer, SAINT, TabTransformer
# Dataset: UNSW-NB15
# ============================================================

import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

from sklearn.preprocessing import label_binarize
from sklearn.metrics import (
    roc_curve,
    auc,
    roc_auc_score,
    precision_recall_curve,
    average_precision_score
)
from IPython.display import display as show_table

# ------------------------------------------------------------
# 1. OUTPUT DIRECTORY
# ------------------------------------------------------------

OUTPUT_DIR = "/content/AI_IDS_ROC_PR_Results"
os.makedirs(OUTPUT_DIR, exist_ok=True)

# ------------------------------------------------------------
# 2. MODELS AND CLASS LABELS
# ------------------------------------------------------------

model_names = [
    "FT-Transformer",
    "SAINT",
    "TabTransformer"
]

class_names = list(target_encoder.classes_)
num_classes = len(class_names)

# Convert actual test labels into a NumPy array
y_true = np.asarray(y_test).astype(int)

# One-hot/binary representation for multiclass ROC and PR
y_binary = label_binarize(
    y_true,
    classes=np.arange(num_classes)
)

auc_rows = []
available_models = []

# ------------------------------------------------------------
# 3. CHECK THAT MODEL PROBABILITIES ARE AVAILABLE
# ------------------------------------------------------------

print("Checking model predictions...")

for model_name in model_names:
    if model_name not in test_probabilities:
        print(f"WARNING: Predictions not found for {model_name}. Skipping.")
        continue

    probabilities = np.asarray(
        test_probabilities[model_name]
    )

    if probabilities.ndim != 2:
        print(
            f"WARNING: Invalid probability shape for {model_name}: "
            f"{probabilities.shape}. Skipping."
        )
        continue

    if probabilities.shape[0] != len(y_true):
        print(
            f"WARNING: Test sample count mismatch for {model_name}. "
            "Skipping."
        )
        continue

    if probabilities.shape[1] != num_classes:
        print(
            f"WARNING: Expected {num_classes} class probabilities for "
            f"{model_name}, but found {probabilities.shape[1]}. "
            "Check the class order. Skipping."
        )
        continue

    if not np.isfinite(probabilities).all():
        print(
            f"WARNING: Non-finite probabilities in {model_name}. Skipping."
        )
        continue

    available_models.append(model_name)

if not available_models:
    raise ValueError(
        "No valid model probabilities were found. "
        "Check test_probabilities and the previous training cells."
    )

print("Models available:", available_models)
print("Number of test samples:", len(y_true))
print("Number of classes:", num_classes)
print("Classes:", class_names)

# ------------------------------------------------------------
# 4. ROC CURVES
# ------------------------------------------------------------

plt.figure(figsize=(10, 8))

for model_name in available_models:

    probabilities = np.asarray(
        test_probabilities[model_name]
    )

    # Micro-average ROC curve across all classes
    fpr, tpr, _ = roc_curve(
        y_binary.ravel(),
        probabilities.ravel()
    )

    micro_auc = auc(fpr, tpr)

    plt.plot(
        fpr,
        tpr,
        linewidth=2,
        label=f"{model_name} (Micro-AUC = {micro_auc:.4f})"
    )

    # Macro-average ROC-AUC across classes
    macro_auc = roc_auc_score(
        y_binary,
        probabilities,
        average="macro"
    )

    # Store metrics for the comparison table
    row = {
        "Model": model_name,
        "Micro ROC-AUC": micro_auc,
        "Macro ROC-AUC": macro_auc
    }

    auc_rows.append(row)

plt.plot(
    [0, 1],
    [0, 1],
    linestyle="--",
    linewidth=1.5,
    label="Random Classifier"
)

plt.xlabel("False Positive Rate", fontsize=12)
plt.ylabel("True Positive Rate", fontsize=12)
plt.title(
    "ROC Curve Comparison - UNSW-NB15",
    fontsize=14,
    fontweight="bold"
)

plt.legend(loc="lower right", fontsize=9)
plt.grid(True, alpha=0.3)
plt.tight_layout()

roc_path = os.path.join(
    OUTPUT_DIR,
    "transformer_ROC_curves.png"
)

plt.savefig(roc_path, dpi=300, bbox_inches="tight")
plt.show()

print("ROC curve saved:", roc_path)

# ------------------------------------------------------------
# 5. PRECISION-RECALL CURVES
# ------------------------------------------------------------

plt.figure(figsize=(10, 8))

for model_name in available_models:

    probabilities = np.asarray(
        test_probabilities[model_name]
    )

    # Micro-average Precision-Recall curve
    precision, recall, _ = precision_recall_curve(
        y_binary.ravel(),
        probabilities.ravel()
    )

    micro_pr_auc = average_precision_score(
        y_binary,
        probabilities,
        average="micro"
    )

    plt.plot(
        recall,
        precision,
        linewidth=2,
        label=f"{model_name} (Micro AP = {micro_pr_auc:.4f})"
    )

    # Macro-average Average Precision across classes
    macro_pr_auc = average_precision_score(
        y_binary,
        probabilities,
        average="macro"
    )

    # Add PR results to the same model's row
    for row in auc_rows:
        if row["Model"] == model_name:
            row["Micro PR-AUC"] = micro_pr_auc
            row["Macro PR-AUC"] = macro_pr_auc

plt.xlabel("Recall", fontsize=12)
plt.ylabel("Precision", fontsize=12)
plt.title(
    "Precision-Recall Curve Comparison - UNSW-NB15",
    fontsize=14,
    fontweight="bold"
)

plt.legend(loc="lower left", fontsize=9)
plt.grid(True, alpha=0.3)
plt.tight_layout()

pr_path = os.path.join(
    OUTPUT_DIR,
    "transformer_PR_curves.png"
)

plt.savefig(pr_path, dpi=300, bbox_inches="tight")
plt.show()

print("Precision-Recall curve saved:", pr_path)

# ------------------------------------------------------------
# 6. CREATE AND DISPLAY AUC COMPARISON TABLE
# ------------------------------------------------------------

auc_df = pd.DataFrame(auc_rows)

metric_columns = [
    "Micro ROC-AUC",
    "Macro ROC-AUC",
    "Micro PR-AUC",
    "Macro PR-AUC"
]

# Convert AUC values into percentages for easier interpretation
auc_percent_df = auc_df.copy()

for column in metric_columns:
    auc_percent_df[column] = (
        auc_percent_df[column] * 100
    ).round(2)

print("\nAUC COMPARISON TABLE (percentages)")
show_table(auc_percent_df)

csv_path = os.path.join(
    OUTPUT_DIR,
    "transformer_ROC_PR_AUC_percent.csv"
)

auc_percent_df.to_csv(csv_path, index=False)

# Also save the original AUC values between 0 and 1
raw_csv_path = os.path.join(
    OUTPUT_DIR,
    "transformer_ROC_PR_AUC_raw.csv"
)

auc_df.to_csv(raw_csv_path, index=False)

print("\nAll outputs saved successfully:")
print("1. ROC curve:", roc_path)
print("2. PR curve:", pr_path)
print("3. AUC percentage table:", csv_path)
print("4. AUC raw-value table:", raw_csv_path)
print("\nOutput folder:", OUTPUT_DIR)

