# ============================================================
# AI-IDS: SIMULATED ZERO-DAY ATTACK DETECTION
# Baseline: Isolation Forest
# Simulated unseen attack: Worms
# ============================================================

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

from sklearn.ensemble import IsolationForest
from sklearn.metrics import (
    classification_report,
    confusion_matrix,
    roc_auc_score,
    average_precision_score
)

# ------------------------------------------------------------
# 1. Identify the Normal and Worms labels
# ------------------------------------------------------------

class_names = list(target_encoder.classes_)

normal_matches = [
    i for i, name in enumerate(class_names)
    if str(name).strip().lower() == "normal"
]

worms_matches = [
    i for i, name in enumerate(class_names)
    if str(name).strip().lower() == "worms"
]

if not normal_matches:
    raise ValueError(
        f"Could not find Normal in target_encoder.classes_: {class_names}"
    )

if not worms_matches:
    raise ValueError(
        f"Could not find Worms in target_encoder.classes_: {class_names}"
    )

normal_id = normal_matches[0]
worms_id = worms_matches[0]

y_train_array = np.asarray(y_train).astype(int)
y_test_array = np.asarray(y_test).astype(int)

Xtr = np.asarray(X_train_num, dtype=np.float32)
Xte = np.asarray(X_test_num, dtype=np.float32)

# ------------------------------------------------------------
# 2. Train ONLY on normal training traffic
# ------------------------------------------------------------

normal_train_mask = y_train_array == normal_id
X_normal_train = Xtr[normal_train_mask]

if len(X_normal_train) < 2:
    raise ValueError("Not enough Normal training samples.")

print("Normal training samples:", len(X_normal_train))
print("Held-out attack category for analysis: Worms")

zero_day_detector = IsolationForest(
    n_estimators=200,
    contamination="auto",
    random_state=42,
    n_jobs=-1
)

zero_day_detector.fit(X_normal_train)

# ------------------------------------------------------------
# 3. Evaluate Normal traffic versus held-out Worms
# ------------------------------------------------------------

evaluation_mask = np.isin(
    y_test_array,
    [normal_id, worms_id]
)

X_eval = Xte[evaluation_mask]
y_eval_original = y_test_array[evaluation_mask]

# Binary evaluation labels:
# 0 = Normal
# 1 = Worms (simulated unseen attack)

y_eval_binary = (y_eval_original == worms_id).astype(int)

if len(np.unique(y_eval_binary)) < 2:
    raise ValueError(
        "The selected test subset must contain both Normal and Worms."
    )

# Isolation Forest: higher scores indicate more normal-like samples.
anomaly_scores = -zero_day_detector.decision_function(X_eval)

# Default threshold corresponds to the model's decision boundary.
predicted_attack = (
    zero_day_detector.predict(X_eval) == -1
).astype(int)

# ------------------------------------------------------------
# 4. Report results
# ------------------------------------------------------------

print("\nZERO-DAY EXPERIMENT: NORMAL VS WORMS")
print("Worms was excluded from model training.")
print("Evaluation samples:", len(y_eval_binary))

print("\nClassification Report:")
print(
    classification_report(
        y_eval_binary,
        predicted_attack,
        labels=[0, 1],
        target_names=["Normal", "Worms (simulated unseen)"],
        zero_division=0
    )
)

cm = confusion_matrix(
    y_eval_binary,
    predicted_attack,
    labels=[0, 1]
)

print("Confusion Matrix:")
print(pd.DataFrame(
    cm,
    index=["Actual Normal", "Actual Worms"],
    columns=["Predicted Normal", "Predicted Attack"]
))

roc_auc = roc_auc_score(y_eval_binary, anomaly_scores)
pr_auc = average_precision_score(y_eval_binary, anomaly_scores)

print(f"\nROC-AUC: {roc_auc:.4f}")
print(f"Average Precision (PR-AUC): {pr_auc:.4f}")

# ------------------------------------------------------------
# 5. Plot anomaly score distributions
# ------------------------------------------------------------

plt.figure(figsize=(9, 5))

plt.hist(
    anomaly_scores[y_eval_binary == 0],
    bins=40,
    alpha=0.7,
    label="Normal traffic"
)

plt.hist(
    anomaly_scores[y_eval_binary == 1],
    bins=40,
    alpha=0.7,
    label="Worms (simulated unseen)"
)

plt.xlabel("Anomaly score (higher = more anomalous)")
plt.ylabel("Number of samples")
plt.title("Zero-Day Baseline: Normal vs Unseen Worms")
plt.legend()
plt.grid(alpha=0.25)
plt.tight_layout()

plt.savefig(
    "/content/AI_IDS_ZeroDay_Worms_Scores.png",
    dpi=300,
    bbox_inches="tight"
)

plt.show()

# Save the sample-level results
zero_day_results = pd.DataFrame({
    "Actual_Class": [
        "Worms" if value == worms_id else "Normal"
        for value in y_eval_original
    ],
    "Actual_Binary_Label": y_eval_binary,
    "Anomaly_Score": anomaly_scores,
    "Predicted_Attack": predicted_attack
})

zero_day_results.to_csv(
    "/content/AI_IDS_ZeroDay_Worms_Results.csv",
    index=False
)

print("\nSaved:")
print("/content/AI_IDS_ZeroDay_Worms_Scores.png")
print("/content/AI_IDS_ZeroDay_Worms_Results.csv")

# ============================================================
# AI-IDS: FALSE-POSITIVE RATE AND ATTACK DETECTION ANALYSIS
# Model: FT-Transformer
# Dataset: UNSW-NB15
# ============================================================

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

from sklearn.metrics import confusion_matrix, classification_report

# 1. Get FT-Transformer predictions
model_name = "FT-Transformer"

if model_name not in test_probabilities:
    raise KeyError(
        "FT-Transformer predictions are missing. "
        "Run the model prediction cell first."
    )

probabilities = np.asarray(test_probabilities[model_name])
y_true = np.asarray(y_test).astype(int)
y_pred = np.argmax(probabilities, axis=1)

class_names = list(target_encoder.classes_)

normal_matches = [
    i for i, name in enumerate(class_names)
    if str(name).strip().lower() == "normal"
]

if not normal_matches:
    raise ValueError(
        f"Normal class not found. Available classes: {class_names}"
    )

normal_id = normal_matches[0]

# 2. Overall multiclass confusion matrix
cm = confusion_matrix(
    y_true,
    y_pred,
    labels=np.arange(len(class_names))
)

# 3. Treat Normal as benign and every attack class as malicious.
# False positive = actual Normal traffic predicted as an attack.
# False negative = actual attack traffic predicted as Normal.

actual_normal = y_true == normal_id
actual_attack = ~actual_normal

predicted_normal = y_pred == normal_id
predicted_attack = ~predicted_normal

FP = int(np.sum(actual_normal & predicted_attack))
TN = int(np.sum(actual_normal & predicted_normal))
FN = int(np.sum(actual_attack & predicted_normal))
TP = int(np.sum(actual_attack & predicted_attack))

fpr = FP / (FP + TN) if (FP + TN) else 0.0
fnr = FN / (FN + TP) if (FN + TP) else 0.0
attack_detection_rate = TP / (TP + FN) if (TP + FN) else 0.0
normal_recall = TN / (TN + FP) if (TN + FP) else 0.0

# 4. Display results
metrics_df = pd.DataFrame({
    "Metric": [
        "False Positives (FP)",
        "True Negatives (TN)",
        "False Negatives (FN)",
        "True Positives (TP)",
        "False-Positive Rate (%)",
        "False-Negative Rate (%)",
        "Attack Detection Rate / Recall (%)",
        "Normal Traffic Correctly Identified (%)"
    ],
    "Value": [
        FP,
        TN,
        FN,
        TP,
        round(fpr * 100, 2),
        round(fnr * 100, 2),
        round(attack_detection_rate * 100, 2),
        round(normal_recall * 100, 2)
    ]
})

from IPython.display import display as show_table

print("FT-TRANSFORMER: BENIGN VS ATTACK EVALUATION")
show_table(metrics_df)

# 5. Save results
metrics_df.to_csv(
    "/content/FT_Transformer_False_Alarm_Metrics.csv",
    index=False
)

# 6. Plot the four binary outcomes
plt.figure(figsize=(8, 5))

outcome_names = ["FP", "TN", "FN", "TP"]
outcome_values = [FP, TN, FN, TP]

plt.bar(outcome_names, outcome_values)
plt.title("FT-Transformer: Benign vs Attack Outcomes")
plt.xlabel("Prediction Outcome")
plt.ylabel("Number of Test Samples")
plt.grid(axis="y", alpha=0.3)
plt.tight_layout()

plt.savefig(
    "/content/FT_Transformer_False_Alarm_Analysis.png",
    dpi=300,
    bbox_inches="tight"
)

plt.show()

print("Saved:")
print("/content/FT_Transformer_False_Alarm_Metrics.csv")
print("/content/FT_Transformer_False_Alarm_Analysis.png")

# ============================================================
# AI-IDS: FAR REDUCTION THROUGH THRESHOLD ANALYSIS
# Model: FT-Transformer | Dataset: UNSW-NB15
#
# Binary decision:
# P(Normal) >= threshold  -> predict Normal
# P(Normal) < threshold   -> predict Attack
# ============================================================

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from IPython.display import display as show_table

# 1. Load existing predictions
model_name = "FT-Transformer"

if model_name not in test_probabilities:
    raise KeyError(
        "FT-Transformer predictions not found. "
        "Run your prediction cell first."
    )

probs = np.asarray(test_probabilities[model_name])
y_true = np.asarray(y_test).astype(int)
class_names = list(target_encoder.classes_)

normal_matches = [
    i for i, name in enumerate(class_names)
    if str(name).strip().lower() == "normal"
]

if not normal_matches:
    raise ValueError("Normal class was not found.")

normal_id = normal_matches[0]
p_normal = probs[:, normal_id]

if len(p_normal) != len(y_true):
    raise ValueError("Prediction and test-label counts do not match.")

# 2. Binary ground truth: 0 = Normal, 1 = Attack
y_attack = (y_true != normal_id).astype(int)

# 3. Evaluate candidate thresholds
thresholds = np.unique(
    np.concatenate([
        np.linspace(0.01, 0.99, 99),
        [p_normal.min(), p_normal.max()]
    ])
)

rows = []

for threshold in thresholds:

    # Predict Normal when its probability meets the threshold
    pred_attack = (p_normal < threshold).astype(int)

    actual_normal = (y_attack == 0)
    actual_attack = (y_attack == 1)

    FP = int(np.sum(actual_normal & (pred_attack == 1)))
    TN = int(np.sum(actual_normal & (pred_attack == 0)))
    FN = int(np.sum(actual_attack & (pred_attack == 0)))
    TP = int(np.sum(actual_attack & (pred_attack == 1)))

    far = FP / (FP + TN) if (FP + TN) else 0.0
    attack_recall = TP / (TP + FN) if (TP + FN) else 0.0

    rows.append({
        "Normal_Threshold": float(threshold),
        "False_Positives": FP,
        "False_Negatives": FN,
        "FAR_Percent": far * 100,
        "Attack_Recall_Percent": attack_recall * 100
    })

threshold_df = pd.DataFrame(rows)

# 4. Show the trade-off for a minimum 99% attack recall
minimum_recall = 99.0

eligible = threshold_df[
    threshold_df["Attack_Recall_Percent"] >= minimum_recall
].copy()

if eligible.empty:
    print(
        f"No tested threshold achieved {minimum_recall:.1f}% attack recall."
    )
    print("Showing the 10 thresholds with the highest attack recall:")
    show_table(
        threshold_df.sort_values(
            "Attack_Recall_Percent", ascending=False
        ).head(10).round(3)
    )
else:
    # Lowest FAR among thresholds satisfying the recall requirement
    best = eligible.sort_values(
        ["FAR_Percent", "Normal_Threshold"],
        ascending=[True, True]
    ).iloc[0]

    print("BEST CANDIDATE UNDER THE 99% RECALL REQUIREMENT")
    show_table(pd.DataFrame([best]).round(3))

    print("\nTop candidate thresholds:")
    show_table(
        eligible.sort_values("FAR_Percent").head(10).round(3)
    )

# 5. Save all threshold results
csv_path = "/content/FT_Transformer_Threshold_Analysis.csv"
threshold_df.to_csv(csv_path, index=False)

# 6. Plot FAR against attack recall
plt.figure(figsize=(9, 6))

plt.plot(
    threshold_df["Attack_Recall_Percent"],
    threshold_df["FAR_Percent"],
    marker=".",
    linewidth=1.5
)

plt.xlabel("Attack Recall (%)")
plt.ylabel("False-Positive Rate (%)")
plt.title("FT-Transformer: FAR vs Attack Recall")
plt.grid(alpha=0.3)
plt.tight_layout()

plot_path = "/content/FT_Transformer_FAR_Threshold_Curve.png"
plt.savefig(plot_path, dpi=300, bbox_inches="tight")
plt.show()

print("\nSaved threshold analysis:", csv_path)
print("Saved trade-off graph:", plot_path)

print(
    "\nIMPORTANT: This is exploratory because it uses test labels "
    "to select a threshold. Choose the final threshold using validation "
    "data, then evaluate it once on the untouched test set."
)

# ============================================================
# AI-IDS: BASELINE VS THRESHOLD-BASED FAR COMPARISON
# ============================================================

import numpy as np
import pandas as pd
from IPython.display import display as show_table

# Load predictions and true labels
probs = np.asarray(test_probabilities["FT-Transformer"])
y_true = np.asarray(y_test).astype(int)
class_names = list(target_encoder.classes_)

normal_id = next(
    i for i, name in enumerate(class_names)
    if str(name).strip().lower() == "normal"
)

p_normal = probs[:, normal_id]
y_attack = (y_true != normal_id).astype(int)

# Original baseline: multiclass argmax, then Normal vs Attack
baseline_class_pred = np.argmax(probs, axis=1)
baseline_attack_pred = (baseline_class_pred != normal_id).astype(int)

def calculate_metrics(y_actual, y_predicted):
    actual_normal = (y_actual == 0)
    actual_attack = (y_actual == 1)

    FP = int(np.sum(actual_normal & (y_predicted == 1)))
    TN = int(np.sum(actual_normal & (y_predicted == 0)))
    FN = int(np.sum(actual_attack & (y_predicted == 0)))
    TP = int(np.sum(actual_attack & (y_predicted == 1)))

    return {
        "FP": FP,
        "TN": TN,
        "FN": FN,
        "TP": TP,
        "FAR (%)": 100 * FP / (FP + TN) if FP + TN else 0,
        "Attack Recall (%)": 100 * TP / (TP + FN) if TP + FN else 0
    }

baseline = calculate_metrics(y_attack, baseline_attack_pred)

# Read the threshold analysis from the previous cell
threshold_path = "/content/FT_Transformer_Threshold_Analysis.csv"
threshold_df = pd.read_csv(threshold_path)

minimum_recall = 99.0
eligible = threshold_df[
    threshold_df["Attack_Recall_Percent"] >= minimum_recall
]

if eligible.empty:
    raise ValueError(
        "No threshold met the 99% recall target. "
        "Review the threshold analysis before proceeding."
    )

best = eligible.sort_values("FAR_Percent").iloc[0]
selected_threshold = float(best["Normal_Threshold"])

# Candidate threshold decision
candidate_attack_pred = (
    p_normal < selected_threshold
).astype(int)

candidate = calculate_metrics(y_attack, candidate_attack_pred)

comparison = pd.DataFrame([
    {
        "Method": "Original argmax",
        **baseline
    },
    {
        "Method": f"Threshold = {selected_threshold:.4f}",
        **candidate
    }
])

print("BASELINE VS CANDIDATE COMPARISON")
show_table(comparison.round(3))

far_reduction = baseline["FAR (%)"] - candidate["FAR (%)"]

print(f"\nFAR change: {far_reduction:.2f} percentage points")

if far_reduction > 0:
    print("FAR decreased on this evaluation set.")
elif far_reduction < 0:
    print("FAR increased on this evaluation set.")
else:
    print("FAR did not change.")

print(
    "\nCaution: the candidate threshold was selected using test results. "
    "This comparison is exploratory, not a final unbiased evaluation."
)

