# AI-IDS: FT-TRANSFORMER INFERENCE TIME AND THROUGHPUT
# Dataset: UNSW-NB15
# ============================================================

import time
import numpy as np
import pandas as pd
import torch
import matplotlib.pyplot as plt

from IPython.display import display as show_table

model = trained_models["FT-Transformer"]
model.eval()

# Convert existing preprocessed features into tensors
X_num = torch.as_tensor(
    np.asarray(X_test_num),
    dtype=torch.float32,
    device=DEVICE
)

X_cat = torch.as_tensor(
    np.asarray(X_test_cat),
    dtype=torch.long,
    device=DEVICE
)

# Check data consistency
assert len(X_num) == len(X_cat), "Numeric/categorical sample counts differ."

def synchronize_device():
    if torch.cuda.is_available() and str(DEVICE).startswith("cuda"):
        torch.cuda.synchronize()

# Warm-up helps reduce first-call overhead
warmup_size = min(256, len(X_num))

with torch.inference_mode():
    _ = model(X_num[:warmup_size], X_cat[:warmup_size])
    synchronize_device()

# Test several batch sizes
batch_sizes = [1, 32, 128, 512, 1024]
batch_sizes = [b for b in batch_sizes if b <= len(X_num)]

timing_rows = []

for batch_size in batch_sizes:

    elapsed_runs = []
    total_samples = len(X_num)

    # Repeat measurements for more stable timing
    for repeat in range(3):
        synchronize_device()
        start = time.perf_counter()

        with torch.inference_mode():
            for start_idx in range(0, total_samples, batch_size):
                end_idx = min(start_idx + batch_size, total_samples)
                _ = model(X_num[start_idx:end_idx], X_cat[start_idx:end_idx])

        synchronize_device()
        elapsed = time.perf_counter() - start
        elapsed_runs.append(elapsed)

    elapsed_seconds = float(np.median(elapsed_runs))

    timing_rows.append({
        "Batch Size": batch_size,
        "Samples": total_samples,
        "Median Total Time (s)": elapsed_seconds,
        "Milliseconds per Sample": (
            elapsed_seconds / total_samples * 1000
        ),
        "Throughput (samples/s)": (
            total_samples / elapsed_seconds
        )
    })

timing_df = pd.DataFrame(timing_rows)

print("FT-TRANSFORMER INFERENCE BENCHMARK")
show_table(timing_df.round(4))

# Save measurements
timing_df.to_csv(
    "/content/FT_Transformer_Inference_Benchmark.csv",
    index=False
)

# Plot throughput by batch size
plt.figure(figsize=(8, 5))
plt.plot(
    timing_df["Batch Size"],
    timing_df["Throughput (samples/s)"],
    marker="o"
)

plt.xlabel("Batch Size")
plt.ylabel("Throughput (samples per second)")
plt.title("FT-Transformer Inference Throughput")
plt.grid(alpha=0.3)
plt.tight_layout()

plt.savefig(
    "/content/FT_Transformer_Inference_Throughput.png",
    dpi=300,
    bbox_inches="tight"
)

plt.show()

print("Saved benchmark table:")
print("/content/FT_Transformer_Inference_Benchmark.csv")
print("Saved throughput plot:")
print("/content/FT_Transformer_Inference_Throughput.png")
print("\nDevice used:", DEVICE)

import time
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import torch
from IPython.display import display as show_table

# 1. Select the existing trained model
model = trained_models["FT-Transformer"]
model.eval()

# 2. Prepare the existing test inputs
num_tensor = torch.as_tensor(
    np.asarray(X_test_num, dtype=np.float32),
    dtype=torch.float32,
    device=DEVICE
)

cat_tensor = torch.as_tensor(
    np.asarray(X_test_cat, dtype=np.int64),
    dtype=torch.long,
    device=DEVICE
)

# Confirm the test data size
print("Test samples:", len(num_tensor))
print("Device:", DEVICE)

# 3. Warm up the model
with torch.no_grad():
    n = min(32, len(num_tensor))
    _ = model(num_tensor[:n], cat_tensor[:n])

if DEVICE.type == "cuda":
    torch.cuda.synchronize()

# 4. Benchmark different batch sizes
batch_sizes = [1, 32, 128, 512, 1024]
results = []

for batch_size in batch_sizes:
    times = []

    for repeat in range(3):
        if DEVICE.type == "cuda":
            torch.cuda.synchronize()

        start = time.perf_counter()

        with torch.no_grad():
            for start_idx in range(0, len(num_tensor), batch_size):
                end_idx = min(
                    start_idx + batch_size,
                    len(num_tensor)
                )

                _ = model(
                    num_tensor[start_idx:end_idx],
                    cat_tensor[start_idx:end_idx]
                )

        if DEVICE.type == "cuda":
            torch.cuda.synchronize()

        times.append(time.perf_counter() - start)

    median_seconds = float(np.median(times))

    results.append({
        "Batch Size": batch_size,
        "Median Total Time (seconds)": median_seconds,
        "Average Time per Flow (ms)": (
            median_seconds / len(num_tensor)
        ) * 1000,
        "Throughput (flows/second)": (
            len(num_tensor) / median_seconds
        )
    })

# 5. Display and save the results
benchmark_df = pd.DataFrame(results)

show_table(benchmark_df.round(4))

benchmark_df.to_csv(
    "/content/FT_Transformer_Inference_Benchmark.csv",
    index=False
)

# 6. Plot throughput as a line graph
plt.figure(figsize=(8, 5))

plt.plot(
    benchmark_df["Batch Size"],
    benchmark_df["Throughput (flows/second)"],
    marker="o",
    linewidth=2
)

plt.xlabel("Batch size")
plt.ylabel("Throughput (flows/second)")
plt.title("FT-Transformer Inference Throughput")
plt.grid(True, alpha=0.3)
plt.tight_layout()

plt.savefig(
    "/content/FT_Transformer_Inference_Throughput.png",
    dpi=300,
    bbox_inches="tight"
)

plt.show()

print("Inference benchmark completed.")
print("Results saved to /content/FT_Transformer_Inference_Benchmark.csv")

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import torch
from sklearn.metrics import f1_score

# Use the existing trained model and test data
model = trained_models["FT-Transformer"]
model.eval()

# Feature names from the original UNSW-NB15 training data
excluded = {"id", "label", "attack_cat"}
feature_names = [
    c for c in train_df.columns if c not in excluded
]

Xn = np.asarray(X_test_num, dtype=np.float32)
Xc = np.asarray(X_test_cat, dtype=np.int64)
y = np.asarray(y_test).astype(int)

# Use a reproducible sample to reduce runtime
rng = np.random.default_rng(42)
sample_size = min(2000, len(y))
idx = rng.choice(len(y), size=sample_size, replace=False)

Xn_sample = Xn[idx].copy()
Xc_sample = Xc[idx].copy()
y_sample = y[idx]

def predict_classes(num_data, cat_data, batch_size=256):
    predictions = []

    with torch.no_grad():
        for start in range(0, len(num_data), batch_size):
            end = min(start + batch_size, len(num_data))

            num_tensor = torch.as_tensor(
                num_data[start:end],
                dtype=torch.float32,
                device=DEVICE
            )
            cat_tensor = torch.as_tensor(
                cat_data[start:end],
                dtype=torch.long,
                device=DEVICE
            )

            logits = model(num_tensor, cat_tensor)
            predictions.extend(
                logits.argmax(dim=1).cpu().numpy()
            )

    return np.asarray(predictions)

baseline_pred = predict_classes(Xn_sample, Xc_sample)
baseline_f1 = f1_score(
    y_sample, baseline_pred,
    average="macro",
    zero_division=0
)

# Shuffle one input column at a time
records = []

for j in range(Xn_sample.shape[1]):
    shuffled = Xn_sample.copy()
    shuffled[:, j] = rng.permutation(shuffled[:, j])

    pred = predict_classes(shuffled, Xc_sample)
    score = f1_score(
        y_sample, pred,
        average="macro",
        zero_division=0
    )

    records.append({
        "Feature": f"Numeric feature {j + 1}",
        "Feature Index": j,
        "Baseline Macro F1": baseline_f1,
        "Shuffled Macro F1": score,
        "Importance (F1 decrease)": baseline_f1 - score
    })

importance_df = pd.DataFrame(records).sort_values(
    "Importance (F1 decrease)", ascending=True
)

importance_df.to_csv(
    "/content/FT_Transformer_Permutation_Importance.csv",
    index=False
)

# Dot plot of the 15 most influential numeric features
top = importance_df.tail(15)

plt.figure(figsize=(9, 6))
plt.scatter(
    top["Importance (F1 decrease)"],
    top["Feature"],
    s=65
)
plt.axvline(0, linestyle="--")
plt.xlabel("Decrease in macro-F1 after shuffling")
plt.ylabel("Numeric feature index")
plt.title("FT-Transformer: Permutation Importance")
plt.grid(axis="x", alpha=0.3)
plt.tight_layout()
plt.savefig(
    "/content/FT_Transformer_Permutation_Importance.png",
    dpi=300,
    bbox_inches="tight"
)
plt.show()

print("Baseline macro-F1 on sample:", round(baseline_f1, 4))
print("Saved permutation-importance CSV and plot.")

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from sklearn.metrics import classification_report, confusion_matrix
from IPython.display import display as show_table

# Actual labels and existing FT-Transformer predictions
y_true = np.asarray(y_test).astype(int)
probs = np.asarray(test_probabilities["FT-Transformer"])
