# Baseline models for UNSW-NB15
import time
import numpy as np
import pandas as pd

from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import (
    accuracy_score, precision_score, recall_score, f1_score
)
from sklearn.preprocessing import OneHotEncoder
from sklearn.compose import ColumnTransformer
from sklearn.pipeline import make_pipeline

# Verify required variables
required = [
    "X_train_num", "X_train_cat",
    "X_test_num", "X_test_cat", "y_train", "y_test"
]
missing = [v for v in required if v not in globals()]

if missing:
    print("Required variables missing:", missing)
    print("Please share this message before running baseline training.")
else:
    # Convert encoded features into one consistent numeric matrix.
    Xtr_num = np.asarray(X_train_num, dtype=np.float32)
    Xte_num = np.asarray(X_test_num, dtype=np.float32)
    Xtr_cat = np.asarray(X_train_cat, dtype=np.float32)
    Xte_cat = np.asarray(X_test_cat, dtype=np.float32)

    Xtr = np.concatenate([Xtr_num, Xtr_cat], axis=1)
    Xte = np.concatenate([Xte_num, Xte_cat], axis=1)

    ytr = np.asarray(y_train).astype(int)
    yte = np.asarray(y_test).astype(int)

    baseline_results = []

    rf = RandomForestClassifier(
        n_estimators=100,
        class_weight="balanced",
        random_state=42,
        n_jobs=-1
    )

    start = time.perf_counter()
    rf.fit(Xtr, ytr)
    rf_train_time = time.perf_counter() - start

    start = time.perf_counter()
    rf_pred = rf.predict(Xte)
    rf_inference_time = time.perf_counter() - start

    baseline_results.append({
        "Model": "Random Forest",
        "Accuracy (%)": 100 * accuracy_score(yte, rf_pred),
        "Macro Precision (%)": 100 * precision_score(
            yte, rf_pred, average="macro", zero_division=0
        ),
        "Macro Recall (%)": 100 * recall_score(
            yte, rf_pred, average="macro", zero_division=0
        ),
        "Macro F1 (%)": 100 * f1_score(
            yte, rf_pred, average="macro", zero_division=0
        ),
        "Training Time (s)": rf_train_time,
        "Test Inference (s)": rf_inference_time
    })

    print("Random Forest completed.")

    # Train XGBoost if installed
    try:
        from xgboost import XGBClassifier

        xgb = XGBClassifier(
            n_estimators=100,
            max_depth=6,
            learning_rate=0.1,
            objective="multi:softprob",
            num_class=len(np.unique(ytr)),
            eval_metric="mlogloss",
            tree_method="hist",
            random_state=42,
            n_jobs=-1
        )

        start = time.perf_counter()
        xgb.fit(Xtr, ytr)
        xgb_train_time = time.perf_counter() - start

        start = time.perf_counter()
        xgb_pred = xgb.predict(Xte)
        xgb_inference_time = time.perf_counter() - start

        baseline_results.append({
            "Model": "XGBoost",
            "Accuracy (%)": 100 * accuracy_score(yte, xgb_pred),
            "Macro Precision (%)": 100 * precision_score(
                yte, xgb_pred, average="macro", zero_division=0
            ),
            "Macro Recall (%)": 100 * recall_score(
                yte, xgb_pred, average="macro", zero_division=0
            ),
            "Macro F1 (%)": 100 * f1_score(
                yte, xgb_pred, average="macro", zero_division=0
            ),
            "Training Time (s)": xgb_train_time,
            "Test Inference (s)": xgb_inference_time
        })

        print("XGBoost completed.")

    except ImportError:
        print("XGBoost is not installed. Run: %pip install xgboost")

    baseline_df = pd.DataFrame(baseline_results)
    baseline_df.to_csv("/content/AI_IDS_Baseline_Results.csv", index=False)

    print("\nBaseline results:")
    print(baseline_df.round(3).to_string(index=False))
    print("\nSaved to /content/AI_IDS_Baseline_Results.csv")

# ============================================================
# AI-BASED INTRUSION DETECTION SYSTEM (AI-IDS)
# UNSW-NB15: Complete Model Comparison and Visualization
#
# Models:
#   FT-Transformer, SAINT, TabTransformer,
#   Transformer Ensemble, Random Forest, XGBoost
#
# Uses existing results; does NOT retrain models.
# ============================================================

import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from IPython.display import display as show_table

# ------------------------------------------------------------
# 1. OUTPUT DIRECTORY
# ------------------------------------------------------------
OUTPUT_DIR = "/content/AI_IDS_Final_Comparison"
os.makedirs(OUTPUT_DIR, exist_ok=True)

# ------------------------------------------------------------
# 2. CHECK EXISTING RESULTS
# ------------------------------------------------------------
if "results_df" not in globals():
    raise NameError(
        "results_df is missing. Run the cell that evaluates "
        "your existing Transformer models first."
    )

if "baseline_df" not in globals():
    raise NameError(
        "baseline_df is missing. Run the Random Forest and "
        "XGBoost baseline cell first."
    )

transformers = results_df.copy()
baselines = baseline_df.copy()

print("Transformer models found:", transformers["Model"].tolist())
print("Baseline models found:", baselines["Model"].tolist())

# ------------------------------------------------------------
# 3. STANDARDIZE COLUMN NAMES
# ------------------------------------------------------------
transformers = transformers.rename(columns={
    "Training Seconds": "Training Time (s)",
    "Test Inference Seconds": "Test Inference (s)"
})

baselines = baselines.rename(columns={
    "Accuracy (%)": "Accuracy",
    "Macro Precision (%)": "Macro Precision",
    "Macro Recall (%)": "Macro Recall",
    "Macro F1 (%)": "Macro F1",
    "Training Time (s)": "Training Time (s)",
    "Test Inference (s)": "Test Inference (s)"
})

metrics = [
    "Accuracy",
    "Macro Precision",
    "Macro Recall",
    "Macro F1"
]

# ------------------------------------------------------------
# 4. CONVERT METRICS TO PERCENTAGES
# Transformer metrics are stored as fractions (0 to 1).
# Baseline metrics are already percentages (0 to 100).
# ------------------------------------------------------------
for col in metrics:
    if col not in transformers.columns:
        raise ValueError(
            f"Missing Transformer metric: {col}"
        )

    transformers[col] = pd.to_numeric(
        transformers[col], errors="coerce"
    ) * 100

    if col not in baselines.columns:
        raise ValueError(
            f"Missing baseline metric: {col}"
        )

    baselines[col] = pd.to_numeric(
        baselines[col], errors="coerce"
    )

# ------------------------------------------------------------
# 5. COMBINE ALL MODEL RESULTS
# ------------------------------------------------------------
comparison_columns = [
    "Model",
    "Accuracy",
    "Macro Precision",
    "Macro Recall",
    "Macro F1",
    "Training Time (s)",
    "Test Inference (s)"
]

combined = pd.concat(
    [
        transformers.reindex(columns=comparison_columns),
        baselines.reindex(columns=comparison_columns)
    ],
    ignore_index=True
)

# Avoid accidentally listing a model twice
combined = combined.drop_duplicates(
    subset=["Model"], keep="last"
).reset_index(drop=True)

# Keep full precision in saved CSV; round only the displayed table
csv_path = os.path.join(
    OUTPUT_DIR, "AI_IDS_Combined_Model_Comparison.csv"
)
combined.to_csv(csv_path, index=False)

print("\n========== COMBINED MODEL COMPARISON ==========")
show_table(combined.round(2))

# ------------------------------------------------------------
# 6. IDENTIFY BEST SCORES
# ------------------------------------------------------------
print("\n========== BEST RESULTS ==========")

for metric in metrics:
    valid = combined.dropna(subset=[metric])

    if len(valid):
        best_row = valid.loc[valid[metric].idxmax()]
        print(
            f"Best {metric}: {best_row['Model']} "
            f"({best_row[metric]:.2f}%)"
        )

# ------------------------------------------------------------
# 7. DOT PLOT: MACRO-F1 COMPARISON
# ------------------------------------------------------------
plot_df = combined.dropna(subset=["Macro F1"]).sort_values(
    "Macro F1"
)

fig, ax = plt.subplots(figsize=(10, 5.5))
ax.scatter(
    plot_df["Macro F1"],
    plot_df["Model"],
    s=100
)

ax.set_xlabel("Macro-F1 (%)")
ax.set_ylabel("Model")
ax.set_title("UNSW-NB15: Macro-F1 Comparison")
ax.grid(axis="x", linestyle="--", alpha=0.4)

fig.tight_layout()
fig.savefig(
    os.path.join(OUTPUT_DIR, "MacroF1_Dot_Plot.png"),
    dpi=300,
    bbox_inches="tight"
)
plt.show()
plt.close(fig)

# ------------------------------------------------------------
# 8. SCATTER PLOT: ACCURACY VS MACRO-F1
# Shows whether high accuracy corresponds to balanced
# performance across the ten attack classes.
# ------------------------------------------------------------
plot_df = combined.dropna(
    subset=["Accuracy", "Macro F1"]
)

fig, ax = plt.subplots(figsize=(8, 6))

ax.scatter(
    plot_df["Accuracy"],
    plot_df["Macro F1"],
    s=100
)

for _, row in plot_df.iterrows():
    ax.annotate(
        row["Model"],
        (row["Accuracy"], row["Macro F1"]),
        xytext=(5, 5),
        textcoords="offset points",
        fontsize=8
    )

ax.set_xlabel("Accuracy (%)")
ax.set_ylabel("Macro-F1 (%)")
ax.set_title("Accuracy vs Macro-F1 Across AI-IDS Models")
ax.grid(linestyle="--", alpha=0.4)

fig.tight_layout()
fig.savefig(
    os.path.join(OUTPUT_DIR, "Accuracy_vs_MacroF1.png"),
    dpi=300,
    bbox_inches="tight"
)
plt.show()
plt.close(fig)

# ------------------------------------------------------------
# 9. SCATTER PLOT: TRAINING TIME VS MACRO-F1
# ------------------------------------------------------------
plot_df = combined.dropna(
    subset=["Training Time (s)", "Macro F1"]
)

fig, ax = plt.subplots(figsize=(8, 6))

ax.scatter(
    plot_df["Training Time (s)"],
    plot_df["Macro F1"],
    s=100
)

for _, row in plot_df.iterrows():
    ax.annotate(
        row["Model"],
        (row["Training Time (s)"], row["Macro F1"]),
        xytext=(5, 5),
        textcoords="offset points",
        fontsize=8
    )

ax.set_xlabel("Training Time (seconds)")
ax.set_ylabel("Macro-F1 (%)")
ax.set_title("Training Cost vs Macro-F1")
ax.grid(linestyle="--", alpha=0.4)

fig.tight_layout()
fig.savefig(
    os.path.join(OUTPUT_DIR, "TrainingTime_vs_MacroF1.png"),
    dpi=300,
    bbox_inches="tight"
)
plt.show()
plt.close(fig)

# ------------------------------------------------------------
# 10. INFERENCE TIME COMPARISON
# ------------------------------------------------------------
plot_df = combined.dropna(
    subset=["Test Inference (s)"]
).sort_values("Test Inference (s)")

fig, ax = plt.subplots(figsize=(10, 5.5))

ax.scatter(
    plot_df["Test Inference (s)"],
    plot_df["Model"],
    s=100
)

ax.set_xlabel("Total Test Inference Time (seconds)")
ax.set_ylabel("Model")
ax.set_title("UNSW-NB15: Test Inference Time Comparison")
ax.grid(axis="x", linestyle="--", alpha=0.4)

fig.tight_layout()
fig.savefig(
    os.path.join(OUTPUT_DIR, "InferenceTime_Dot_Plot.png"),
    dpi=300,
    bbox_inches="tight"
)
plt.show()
plt.close(fig)

# ------------------------------------------------------------
# 11. SAVE A PAPER-READY SUMMARY TABLE
# ------------------------------------------------------------
paper_table = combined.copy()

for col in metrics:
    paper_table[col] = paper_table[col].round(2)

for col in ["Training Time (s)", "Test Inference (s)"]:
    paper_table[col] = paper_table[col].round(3)

paper_table.to_csv(
    os.path.join(OUTPUT_DIR, "Paper_Results_Table.csv"),
    index=False
)

print("\n========== FILES SAVED ==========")
for filename in sorted(os.listdir(OUTPUT_DIR)):
    print(os.path.join(OUTPUT_DIR, filename))

print("\nComparison completed. No models were retrained.")

