# AI-IDS: Confusion Matrices for Existing Transformer Models
# ============================================================

import os
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns

from sklearn.metrics import confusion_matrix

OUTPUT_DIR = "/content/AI_IDS_Final_Comparison"
os.makedirs(OUTPUT_DIR, exist_ok=True)

# Use existing test labels and class names
y_true = np.asarray(y_test).astype(int)
class_names = [str(c) for c in target_encoder.classes_]
num_classes = len(class_names)

# Select the existing models that have prediction probabilities
model_names = [
    name for name in [
        "FT-Transformer",
        "SAINT",
        "TabTransformer",
        "Transformer Ensemble"
    ]
    if name in test_probabilities
]

if not model_names:
    raise ValueError(
        "No model probabilities found in test_probabilities."
    )

for model_name in model_names:
    probs = np.asarray(test_probabilities[model_name])
    y_pred = probs.argmax(axis=1)

    if len(y_pred) != len(y_true):
        print(f"Skipping {model_name}: prediction length mismatch.")
        continue

    cm = confusion_matrix(
        y_true,
        y_pred,
        labels=np.arange(num_classes)
    )

    # Normalize by actual class count to reveal minority-class recall
    row_totals = cm.sum(axis=1, keepdims=True)
    cm_normalized = np.divide(
        cm,
        row_totals,
        out=np.zeros_like(cm, dtype=float),
        where=row_totals != 0
    )

    fig, ax = plt.subplots(figsize=(11, 9))

    sns.heatmap(
        cm_normalized,
        cmap="Blues",
        vmin=0,
        vmax=1,
        xticklabels=class_names,
        yticklabels=class_names,
        annot=True,
        fmt=".2f",
        ax=ax
    )

    ax.set_title(f"{model_name}: Normalized Confusion Matrix")
    ax.set_xlabel("Predicted attack class")
    ax.set_ylabel("Actual attack class")
    plt.xticks(rotation=45, ha="right")
    plt.yticks(rotation=0)
    fig.tight_layout()

    safe_name = model_name.replace("-", "_").replace(" ", "_")
    fig.savefig(
        os.path.join(
            OUTPUT_DIR,
            f"{safe_name}_Normalized_Confusion_Matrix.png"
        ),
        dpi=300,
        bbox_inches="tight"
    )
    plt.show()
    plt.close(fig)

    np.savetxt(
        os.path.join(OUTPUT_DIR, f"{safe_name}_Confusion_Matrix.csv"),
        cm,
        delimiter=",",
        fmt="%d"
    )

print("\nConfusion matrices saved in:", OUTPUT_DIR)

# ============================================================
# AI-IDS: Baseline Confusion Matrices and Class-wise Metrics
# ============================================================

import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

from sklearn.metrics import confusion_matrix, classification_report

OUTPUT_DIR = "/content/AI_IDS_Final_Comparison"
os.makedirs(OUTPUT_DIR, exist_ok=True)

y_true = np.asarray(y_test).astype(int)
class_names = [str(c) for c in target_encoder.classes_]
class_ids = np.arange(len(class_names))

baseline_predictions = {}

if "rf_pred" in globals():
    baseline_predictions["Random Forest"] = np.asarray(rf_pred).astype(int)

if "xgb_pred" in globals():
    baseline_predictions["XGBoost"] = np.asarray(xgb_pred).astype(int)

if not baseline_predictions:
    raise NameError(
        "Baseline predictions are not in memory. "
        "Rerun the baseline training cell to recreate rf_pred and xgb_pred."
    )

for model_name, y_pred in baseline_predictions.items():
    if len(y_pred) != len(y_true):
        print(f"Skipping {model_name}: prediction length mismatch.")
        continue

    cm = confusion_matrix(y_true, y_pred, labels=class_ids)

    # Row-normalization: each row shows recall distribution for one class
    row_totals = cm.sum(axis=1, keepdims=True)
    cm_norm = np.divide(
        cm,
        row_totals,
        out=np.zeros_like(cm, dtype=float),
        where=row_totals != 0
    )

    fig, ax = plt.subplots(figsize=(11, 9))
    sns.heatmap(
        cm_norm,
        cmap="Blues",
        vmin=0,
        vmax=1,
        xticklabels=class_names,
        yticklabels=class_names,
        annot=True,
        fmt=".2f",
        ax=ax
    )

    ax.set_title(f"{model_name}: Normalized Confusion Matrix")
    ax.set_xlabel("Predicted class")
    ax.set_ylabel("Actual class")
    plt.xticks(rotation=45, ha="right")
    plt.yticks(rotation=0)
    fig.tight_layout()

    filename = model_name.replace(" ", "_")
    fig.savefig(
        os.path.join(OUTPUT_DIR, f"{filename}_Confusion_Matrix.png"),
        dpi=300,
        bbox_inches="tight"
    )
    plt.show()
    plt.close(fig)

    report = classification_report(
        y_true,
        y_pred,
        labels=class_ids,
        target_names=class_names,
        output_dict=True,
        zero_division=0
    )

    report_df = pd.DataFrame(report).T
    report_df.to_csv(
        os.path.join(OUTPUT_DIR, f"{filename}_Classwise_Report.csv")
    )

    print(f"\n=== {model_name}: Class-wise report ===")
    print(report_df.round(3).to_string())

print("\nBaseline evaluation files saved to:", OUTPUT_DIR)

