# ============================================================
# AI-IDS: COMPLETE XGBOOST CLASS-WISE PERFORMANCE REPORT
# Dataset: UNSW-NB15
# ============================================================

import os
import time
import numpy as np
import pandas as pd

from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report,
    confusion_matrix
)

# ------------------------------------------------------------
# 1. Check that required variables exist
# ------------------------------------------------------------
required_variables = [
    "xgb", "X_test_num", "X_test_cat",
    "y_test", "target_encoder"
]

missing = [
    name for name in required_variables
    if name not in globals()
]

if missing:
    raise NameError(
        f"Missing variables: {missing}\n"
        "Run the earlier data preparation and XGBoost training "
        "cells first. This cell cannot recreate missing data "
        "or a trained model automatically."
    )

# ------------------------------------------------------------
# 2. Prepare test features
#    Use the same feature construction as baseline training
# ------------------------------------------------------------
X_test_baseline = np.concatenate(
    [
        np.asarray(X_test_num),
        np.asarray(X_test_cat)
    ],
    axis=1
)

# ------------------------------------------------------------
# 3. Generate XGBoost predictions
# ------------------------------------------------------------
print("Generating XGBoost predictions...")

start_time = time.time()
xgb_pred = xgb.predict(X_test_baseline)
inference_seconds = time.time() - start_time

y_true = np.asarray(y_test).reshape(-1)
xgb_pred = np.asarray(xgb_pred).reshape(-1)

# ------------------------------------------------------------
# 4. Overall performance metrics
# ------------------------------------------------------------
accuracy = accuracy_score(y_true, xgb_pred)
macro_precision = precision_score(
    y_true, xgb_pred, average="macro", zero_division=0
)
macro_recall = recall_score(
    y_true, xgb_pred, average="macro", zero_division=0
)
macro_f1 = f1_score(
    y_true, xgb_pred, average="macro", zero_division=0
)
weighted_f1 = f1_score(
    y_true, xgb_pred, average="weighted", zero_division=0
)

overall_results = pd.DataFrame([{
    "Model": "XGBoost",
    "Accuracy (%)": accuracy * 100,
    "Macro Precision (%)": macro_precision * 100,
    "Macro Recall (%)": macro_recall * 100,
    "Macro F1 (%)": macro_f1 * 100,
    "Weighted F1 (%)": weighted_f1 * 100,
    "Test Inference Time (seconds)": inference_seconds
}])

print("\n========== OVERALL XGBOOST RESULTS ==========")
print(overall_results.round(3).to_string(index=False))

# ------------------------------------------------------------
# 5. Class-wise performance report
# ------------------------------------------------------------
class_names = list(target_encoder.classes_)
class_ids = list(range(len(class_names)))

report = classification_report(
    y_true,
    xgb_pred,
    labels=class_ids,
    target_names=[str(name) for name in class_names],
    output_dict=True,
    zero_division=0
)

xgb_report_df = pd.DataFrame(report).transpose()

print("\n========== XGBOOST CLASS-WISE PERFORMANCE ==========")
print(xgb_report_df.round(3).to_string())

# ------------------------------------------------------------
# 6. Create output folder and save results
# ------------------------------------------------------------
output_dir = "/content/AI_IDS_Final_Comparison"
os.makedirs(output_dir, exist_ok=True)

overall_results.to_csv(
    os.path.join(output_dir, "XGBoost_Overall_Results.csv"),
    index=False
)

xgb_report_df.to_csv(
    os.path.join(output_dir, "XGBoost_Classwise_Report.csv")
)

# Save confusion matrix
cm = confusion_matrix(
    y_true, xgb_pred, labels=class_ids
)

cm_df = pd.DataFrame(
    cm,
    index=class_names,
    columns=class_names
)

cm_df.to_csv(
    os.path.join(output_dir, "XGBoost_Confusion_Matrix.csv")
)

print("\nAll XGBoost reports saved successfully!")
print("Output folder:", output_dir)

import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

# Output folder
out_dir = "/content/AI_IDS_Final_Comparison"
