width = 0.36

fig, ax = plt.subplots(figsize=(11, 6))
ax.bar(x - width/2, plot_df["Accuracy"], width, label="Accuracy")
ax.bar(x + width/2, plot_df["Macro F1"], width, label="Macro F1")
ax.set_xticks(x)
ax.set_xticklabels(plot_df["Model"], rotation=30, ha="right")
ax.set_ylabel("Score (%)")
ax.set_ylim(0, 100)
ax.set_title("AI-IDS Model Performance Comparison")
ax.legend()
fig.tight_layout()
fig.savefig(os.path.join(out_dir, "Accuracy_MacroF1_Comparison.png"),
            dpi=300, bbox_inches="tight")
plt.show()

# ------------------------------------------------
# Figure 2: Accuracy versus Macro-F1 scatter plot
# ------------------------------------------------
fig, ax = plt.subplots(figsize=(8, 6))
ax.scatter(plot_df["Accuracy"], plot_df["Macro F1"], s=90)

for _, row in plot_df.iterrows():
    ax.annotate(
        row["Model"],
        (row["Accuracy"], row["Macro F1"]),
        xytext=(5, 5),
        textcoords="offset points",
        fontsize=8
    )

ax.set_xlabel("Accuracy (%)")
ax.set_ylabel("Macro F1 (%)")
ax.set_title("Accuracy vs Macro-F1")
ax.grid(True, alpha=0.3)
fig.tight_layout()
fig.savefig(os.path.join(out_dir, "Accuracy_vs_MacroF1.png"),
            dpi=300, bbox_inches="tight")
plt.show()

# ------------------------------------------------
# Figure 3: Training time comparison
# ------------------------------------------------
time_df = combined_df.dropna(subset=["Training Time (s)"]).copy()

fig, ax = plt.subplots(figsize=(9, 5))
ax.scatter(time_df["Model"], time_df["Training Time (s)"], s=90)
ax.set_ylabel("Training time (seconds)")
ax.set_title("Model Training-Time Comparison")
ax.tick_params(axis="x", rotation=30)
ax.grid(True, axis="y", alpha=0.3)
fig.tight_layout()
fig.savefig(os.path.join(out_dir, "Training_Time_Comparison.png"),
            dpi=300, bbox_inches="tight")
plt.show()

print("\nGraphs and comparison table saved in:")
print(out_dir)

