import os
import numpy as np
import matplotlib.pyplot as plt

from sklearn.preprocessing import label_binarize
from sklearn.metrics import precision_recall_curve, average_precision_score

out_dir = "/content/AI_IDS_Final_Comparison"
os.makedirs(out_dir, exist_ok=True)

# Existing transformer probabilities and XGBoost predictions
class_names = list(target_encoder.classes_)
n_classes = len(class_names)

y_true = np.asarray(y_test).reshape(-1)
y_binary = label_binarize(y_true, classes=np.arange(n_classes))

# Include only models with available test probabilities
model_probabilities = {}

for name in ["FT-Transformer", "SAINT", "TabTransformer"]:
    if name in test_probabilities:
        model_probabilities[name] = np.asarray(test_probabilities[name])

# XGBoost probabilities, if the trained model is available
if "xgb" in globals():
    X_test_baseline = np.concatenate(
        [np.asarray(X_test_num), np.asarray(X_test_cat)],
        axis=1
    )
    model_probabilities["XGBoost"] = xgb.predict_proba(
        X_test_baseline
    )

# Plot macro-average precision-recall curves
fig, ax = plt.subplots(figsize=(10, 7))
ap_results = []

for name, probs in model_probabilities.items():
    if probs.shape != y_binary.shape:
        print(
            f"Skipping {name}: probability shape {probs.shape}, "
            f"expected {y_binary.shape}"
        )
        continue

    class_ap = []

    # Plot per-class curves faintly and calculate macro average AP
    for i, class_name in enumerate(class_names):
        precision, recall, _ = precision_recall_curve(
            y_binary[:, i], probs[:, i]
        )
        ap = average_precision_score(
            y_binary[:, i], probs[:, i]
        )
        class_ap.append(ap)

    macro_ap = float(np.mean(class_ap))
    ap_results.append({
        "Model": name,
        "Macro Average Precision (AP) (%)": macro_ap * 100
    })

    # Use a curve for the most frequent class as a visual summary
    # This is explicitly labelled; it is not a macro-average curve.
    most_frequent_class = np.argmax(np.bincount(y_true))
    precision, recall, _ = precision_recall_curve(
        y_binary[:, most_frequent_class],
        probs[:, most_frequent_class]
    )

    ax.plot(
        recall, precision,
        linewidth=2,
        label=f"{name} — {class_names[most_frequent_class]} "
              f"(Macro AP: {macro_ap * 100:.1f}%)"
    )

ax.set_xlabel(
    f"Recall for {class_names[np.argmax(np.bincount(y_true))]} (%)"
)
ax.set_ylabel("Precision (%)")
ax.set_title("Precision–Recall Curves: AI-IDS Model Comparison")
ax.set_xlim(0, 1)
ax.set_ylim(0, 1)

# Show percentage tick labels
ticks = np.linspace(0, 1, 6)
ax.set_xticks(ticks, [f"{v*100:.0f}%" for v in ticks])
ax.set_yticks(ticks, [f"{v*100:.0f}%" for v in ticks])

ax.grid(True, alpha=0.3)
ax.legend(fontsize=8)
fig.tight_layout()

fig.savefig(
    os.path.join(out_dir, "Precision_Recall_Comparison.png"),
    dpi=300,
    bbox_inches="tight"
)
plt.show()

# Save macro AP summary
ap_df = __import__("pandas").DataFrame(ap_results)
ap_df.to_csv(
    os.path.join(out_dir, "PR_Macro_AP_Results.csv"),
    index=False
)

print("\nMacro average precision summary:")
print(ap_df.round(2).to_string(index=False))
print("\nSaved to:", out_dir)

import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from sklearn.preprocessing import label_binarize
from sklearn.metrics import precision_recall_curve, average_precision_score

out_dir = "/content/AI_IDS_Final_Comparison"
os.makedirs(out_dir, exist_ok=True)

class_names = list(target_encoder.classes_)
n_classes = len(class_names)

y_true = np.asarray(y_test).reshape(-1)
y_binary = label_binarize(y_true, classes=np.arange(n_classes))

# Use existing transformer probabilities and XGBoost probabilities
model_probabilities = {}

for name in ["FT-Transformer", "SAINT", "TabTransformer"]:
    if name in test_probabilities:
        model_probabilities[name] = np.asarray(test_probabilities[name])

if "xgb" in globals():
    X_test_baseline = np.concatenate(
        [np.asarray(X_test_num), np.asarray(X_test_cat)], axis=1
    )
    model_probabilities["XGBoost"] = xgb.predict_proba(
        X_test_baseline
    )

fig, ax = plt.subplots(figsize=(10, 7))
summary = []

for name, probs in model_probabilities.items():
    if probs.shape != y_binary.shape:
        print(f"Skipping {name}: incompatible probability shape {probs.shape}")
        continue

    # Micro-average: combine decisions across all classes
    precision, recall, _ = precision_recall_curve(
        y_binary.ravel(), probs.ravel()
    )
    micro_ap = average_precision_score(
        y_binary, probs, average="micro"
    )

    ax.plot(
        recall * 100,
        precision * 100,
        linewidth=2,
        label=f"{name} (Micro-AP: {micro_ap * 100:.2f}%)"
    )

    summary.append({
        "Model": name,
        "Micro Average Precision (%)": micro_ap * 100
    })

ax.set_xlabel("Micro-average Recall (%)")
ax.set_ylabel("Micro-average Precision (%)")
ax.set_title("Multiclass Precision–Recall Comparison — UNSW-NB15")
ax.set_xlim(0, 100)
ax.set_ylim(0, 100)
ax.set_xticks(np.arange(0, 101, 10))
ax.set_yticks(np.arange(0, 101, 10))
ax.grid(True, alpha=0.3)
ax.legend(loc="lower left", fontsize=9)
fig.tight_layout()

fig.savefig(
    os.path.join(out_dir, "Multiclass_MicroAverage_PR_Curve.png"),
    dpi=300, bbox_inches="tight"
)
plt.show()

summary_df = pd.DataFrame(summary).sort_values(
    "Micro Average Precision (%)", ascending=False
)
summary_df.to_csv(
    os.path.join(out_dir, "Multiclass_MicroAverage_AP.csv"),
    index=False
)

print("Multiclass micro-average AP results:")
print(summary_df.round(2).to_string(index=False))
print("\nSaved in:", out_dir)

