import os
import numpy as np
import matplotlib.pyplot as plt
import pandas as pd

from sklearn.metrics import confusion_matrix

out_dir = "/content/AI_IDS_Final_Comparison"
os.makedirs(out_dir, exist_ok=True)

y_true = np.asarray(y_test).reshape(-1)
class_names = [str(c) for c in target_encoder.classes_]
class_ids = np.arange(len(class_names))

# Collect predictions from models already evaluated
model_predictions = {}

for name in ["FT-Transformer", "SAINT", "TabTransformer"]:
    if name in test_probabilities:
        probs = np.asarray(test_probabilities[name])

        if probs.ndim == 2 and probs.shape[0] == len(y_true):
            model_predictions[name] = np.argmax(probs, axis=1)

if "xgb_pred" in globals():
    model_predictions["XGBoost"] = np.asarray(xgb_pred).reshape(-1)

if not model_predictions:
    raise ValueError(
        "No existing predictions were found. "
        "Check that the model evaluation cells have been run."
    )

# Generate one normalized confusion matrix per model
for model_name, y_pred in model_predictions.items():

    if len(y_pred) != len(y_true):
        print(f"Skipping {model_name}: prediction length mismatch.")
        continue

    cm_percent = confusion_matrix(
        y_true,
        y_pred,
        labels=class_ids,
        normalize="true"
    ) * 100

    # Save percentages as CSV
    cm_df = pd.DataFrame(
        cm_percent,
        index=class_names,
        columns=class_names
    )

    safe_name = model_name.replace("-", "_").replace(" ", "_")

    cm_df.to_csv(
        os.path.join(
            out_dir,
            f"{safe_name}_Confusion_Matrix_Percent.csv"
        )
    )

    # Draw heatmap using Matplotlib
    fig, ax = plt.subplots(figsize=(11, 9))

    image = ax.imshow(
        cm_percent,
        interpolation="nearest",
        vmin=0,
        vmax=100,
        aspect="auto"
    )

    fig.colorbar(image, ax=ax, label="Samples (%)")

    ax.set_title(
        f"{model_name}: Normalized Confusion Matrix",
        fontsize=14
    )
    ax.set_xlabel("Predicted Class")
    ax.set_ylabel("Actual Class")

    ax.set_xticks(class_ids)
    ax.set_yticks(class_ids)
    ax.set_xticklabels(
        class_names, rotation=45, ha="right", fontsize=9
    )
    ax.set_yticklabels(class_names, fontsize=9)

    # Annotate each cell with a percentage
    for i in range(len(class_names)):
        for j in range(len(class_names)):
            value = cm_percent[i, j]

            # Keep labels readable
            if value >= 5:
                text_color = "white" if value >= 50 else "black"
                ax.text(
                    j, i, f"{value:.1f}%",
                    ha="center", va="center",
                    fontsize=7, color=text_color
                )

    fig.tight_layout()
    fig.savefig(
        os.path.join(
            out_dir,
            f"{safe_name}_Confusion_Matrix_Percent.png"
        ),
        dpi=300,
        bbox_inches="tight"
    )
    plt.show()
    plt.close(fig)

    print(f"{model_name} confusion matrix saved.")

print("\nCompleted confusion matrices.")
print("Files saved in:", out_dir)
print("Models included:", list(model_predictions.keys()))

