import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

from sklearn.preprocessing import label_binarize
from sklearn.metrics import roc_curve, auc, roc_auc_score

out_dir = "/content/AI_IDS_Final_Comparison"
os.makedirs(out_dir, exist_ok=True)

y_true = np.asarray(y_test).reshape(-1)
class_names = list(target_encoder.classes_)
n_classes = len(class_names)
class_ids = np.arange(n_classes)

y_binary = label_binarize(y_true, classes=class_ids)

# Collect existing probability predictions
model_probabilities = {}

for name in ["FT-Transformer", "SAINT", "TabTransformer"]:
    if name in test_probabilities:
        model_probabilities[name] = np.asarray(
            test_probabilities[name]
        )

# XGBoost probabilities
if "xgb" in globals():
    X_test_baseline = np.concatenate(
        [np.asarray(X_test_num), np.asarray(X_test_cat)],
        axis=1
    )
    model_probabilities["XGBoost"] = xgb.predict_proba(
        X_test_baseline
    )

fig, ax = plt.subplots(figsize=(9, 7))
results = []

for name, probs in model_probabilities.items():

    if probs.shape != y_binary.shape:
        print(f"Skipping {name}: incompatible probability shape.")
        continue

    # Micro-average ROC across all classes
    fpr, tpr, _ = roc_curve(
        y_binary.ravel(),
        probs.ravel()
    )

    roc_auc = auc(fpr, tpr)

    ax.plot(
        fpr * 100,
        tpr * 100,
        linewidth=2,
        label=f"{name} (Micro-AUC: {roc_auc:.4f})"
    )

    # Also calculate macro-average multiclass ROC-AUC
    macro_auc = roc_auc_score(
        y_binary,
        probs,
        average="macro",
        multi_class="ovr"
    )

    results.append({
        "Model": name,
        "Micro ROC-AUC (%)": roc_auc * 100,
        "Macro ROC-AUC (%)": macro_auc * 100
    })

# Random classifier reference line
ax.plot(
    [0, 100], [0, 100],
    linestyle="--",
    linewidth=1,
    label="Random classifier (AUC = 0.50)"
)

ax.set_xlabel("False Positive Rate (%)")
ax.set_ylabel("True Positive Rate / Recall (%)")
ax.set_title("Multiclass ROC Curve — UNSW-NB15")
ax.set_xlim(0, 100)
ax.set_ylim(0, 102)
ax.set_xticks(np.arange(0, 101, 10))
ax.set_yticks(np.arange(0, 101, 10))
ax.grid(True, alpha=0.3)
ax.legend(loc="lower right", fontsize=8)
fig.tight_layout()

fig.savefig(
    os.path.join(out_dir, "Multiclass_ROC_Comparison.png"),
    dpi=300,
    bbox_inches="tight"
)
plt.show()

# Save AUC summary
roc_df = pd.DataFrame(results)
roc_df.to_csv(
    os.path.join(out_dir, "ROC_AUC_Comparison.csv"),
    index=False
)

print("\nROC-AUC RESULTS")
print(roc_df.round(3).to_string(index=False))
print("\nSaved to:", out_dir)

