# STEP 6: Compare current and moderated class weights

import numpy as np
import pandas as pd
import torch

counts = np.bincount(
    np.asarray(y_train).astype(int),
    minlength=NUM_CLASSES
).astype(float)

# Current weights already used in the original training
current_weights = class_weights.detach().cpu().numpy()

# Effective-number weighting moderates extreme weights.
# beta is chosen close to 1 to reduce dominance from rare classes.
beta = 0.99
effective_num = 1.0 - np.power(beta, counts)
moderated_weights = (1.0 - beta) / effective_num

# Normalize weights so their average is approximately 1
moderated_weights = moderated_weights / moderated_weights.mean()

weight_df = pd.DataFrame({
    "Class": [str(x) for x in target_encoder.classes_],
    "Training samples": counts.astype(int),
    "Current weight": current_weights,
    "Moderated weight": moderated_weights
})

print("=== CLASS-WEIGHT COMPARISON ===")
print(weight_df.round(3).to_string(index=False))

print("\nCurrent weight range:",
      round(current_weights.min(), 3), "to",
      round(current_weights.max(), 3))
print("Moderated weight range:",
      round(moderated_weights.min(), 3), "to",
      round(moderated_weights.max(), 3))

print("\nNo model weights or training settings have been changed.")

# STEP 7: Create intermediate class weights

import numpy as np
import pandas as pd
import torch

counts = np.bincount(
    np.asarray(y_train).astype(int),
    minlength=NUM_CLASSES
).astype(float)

# Inverse-frequency weights with square-root moderation
new_weights = 1.0 / np.sqrt(counts)
new_weights = new_weights / new_weights.mean()

weight_comparison = pd.DataFrame({
    "Class": [str(x) for x in target_encoder.classes_],
    "Training samples": counts.astype(int),
    "Old weight": class_weights.detach().cpu().numpy(),
    "New experimental weight": new_weights
})

print(weight_comparison.round(3).to_string(index=False))
print("\nNew weight range:",
      round(new_weights.min(), 3), "to",
      round(new_weights.max(), 3))

# Keep these separate from the existing trained model
experimental_class_weights = torch.tensor(
    new_weights,
    dtype=torch.float32,
    device=DEVICE
)

print("\nExperimental weights prepared.")
print("Original FT-Transformer remains unchanged.")

criterion = nn.CrossEntropyLoss(weight=class_weights)

nn.CrossEntropyLoss(weight=class_weights)

# STEP 8: Prepare experimental weighted loss

import torch
