# STEP 10: Experimental FT-Transformer training
# Original model and baseline results remain unchanged.

import copy
import time
import numpy as np
import torch
import torch.nn as nn
import pandas as pd

from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report
)

# 1. Compute experimental weights using training split ONLY
train_counts = np.bincount(
    np.asarray(yt[train_idx]).astype(int),
    minlength=NUM_CLASSES
).astype(np.float64)

if np.any(train_counts == 0):
    raise ValueError("A class is missing from the training split.")

new_weights = 1.0 / np.sqrt(train_counts)
new_weights = new_weights / new_weights.mean()

experimental_class_weights = torch.tensor(
    new_weights,
    dtype=torch.float32,
    device=DEVICE
)

experimental_criterion = nn.CrossEntropyLoss(
    weight=experimental_class_weights
)

print("Experimental class weights:")
print(pd.DataFrame({
    "Class": target_encoder.classes_,
    "Training samples": train_counts.astype(int),
    "Experimental weight": new_weights.round(4)
}).to_string(index=False))

# 2. Create a fresh model; do not modify the baseline model
experimental_model = FTTransformer().to(DEVICE)

experimental_optimizer = torch.optim.AdamW(
    experimental_model.parameters(),
    lr=LEARNING_RATE,
    weight_decay=1e-4
)

# 3. Train with experimental weighted loss
best_val_f1 = -1.0
best_state = None
start_time = time.perf_counter()

for epoch in range(EPOCHS):
    experimental_model.train()
    total_loss = 0.0
    total_samples = 0

    for xn_batch, xc_batch, y_batch in train_loader:
        xn_batch = xn_batch.to(DEVICE, non_blocking=True)
        xc_batch = xc_batch.to(DEVICE, non_blocking=True)
        y_batch = y_batch.to(DEVICE, non_blocking=True).long()

        experimental_optimizer.zero_grad(set_to_none=True)

        with torch.autocast(
            device_type="cuda",
            dtype=torch.float16,
            enabled=(DEVICE.type == "cuda")
        ):
            logits = experimental_model(xn_batch, xc_batch)
            loss = experimental_criterion(logits, y_batch)

        loss.backward()
        torch.nn.utils.clip_grad_norm_(
            experimental_model.parameters(), 1.0
        )
        experimental_optimizer.step()

        total_loss += loss.item() * len(y_batch)
        total_samples += len(y_batch)

    # Select the best checkpoint using validation macro-F1
    val_probs, val_labels = predict_loader(
        experimental_model, val_loader
    )
    val_predictions = val_probs.argmax(axis=1)

    val_f1 = f1_score(
        val_labels,
        val_predictions,
        average="macro",
        zero_division=0
    )

    mean_loss = total_loss / max(total_samples, 1)

    print(
        f"Experimental FT-Transformer | "
        f"Epoch {epoch + 1}/{EPOCHS} | "
        f"Loss: {mean_loss:.4f} | "
        f"Validation Macro-F1: {val_f1:.4f}"
    )

    if val_f1 > best_val_f1:
        best_val_f1 = val_f1
        best_state = {
            k: v.detach().cpu().clone()
            for k, v in experimental_model.state_dict().items()
        }

# Restore best validation checkpoint
if best_state is None:
    raise RuntimeError("No valid model checkpoint was produced.")

experimental_model.load_state_dict(best_state)
experimental_model.eval()

training_seconds = time.perf_counter() - start_time

# Save separately from the original model
torch.save(
    experimental_model.state_dict(),
    "FT_Transformer_Experimental_Weights.pt"
)

print("\nExperimental training completed.")
print(f"Best validation Macro-F1: {best_val_f1:.4f}")
print(f"Training time: {training_seconds:.1f} seconds")
print("Saved: FT_Transformer_Experimental_Weights.pt")
print("Original baseline model has not been modified.")

# ============================================================
# AI-IDS: BASELINE VS EXPERIMENTAL FT-TRANSFORMER
# UNSW-NB15 — Weighted-Loss Experiment
# ============================================================

import numpy as np
import pandas as pd
from IPython.display import display as show_table
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report
)

# ------------------------------------------------------------
# 1. LOAD BASELINE AND EXPERIMENTAL PREDICTIONS
# ------------------------------------------------------------

if "FT-Transformer" not in test_probabilities:
    raise KeyError(
        "Baseline FT-Transformer predictions are missing. "
        "Run the original model evaluation cell first."
    )

if "experimental_model" not in globals():
    raise NameError(
        "experimental_model is missing. "
        "Run the experimental training cell first."
    )

baseline_probs = np.asarray(
    test_probabilities["FT-Transformer"]
)

experimental_probs, actual_labels = predict_loader(
    experimental_model,
    test_loader
)

actual_labels = np.asarray(actual_labels).astype(int)
baseline_labels = np.asarray(y_test).astype(int)

# Verify that the test labels align with both predictions.
if len(baseline_probs) != len(baseline_labels):
    raise ValueError("Baseline prediction and test-label lengths differ.")

if len(experimental_probs) != len(actual_labels):
    raise ValueError(
        "Experimental prediction and test-label lengths differ."
    )

if not np.array_equal(actual_labels, baseline_labels):
    raise ValueError(
        "Test-label order differs between the two evaluations. "
        "Check the test_loader and y_test before comparing."
    )

if baseline_probs.shape != experimental_probs.shape:
    raise ValueError(
        "Baseline and experimental probability shapes differ."
    )

# ------------------------------------------------------------
# 2. GENERATE CLASS PREDICTIONS
# ------------------------------------------------------------

baseline_predictions = np.argmax(baseline_probs, axis=1)
experimental_predictions = np.argmax(experimental_probs, axis=1)

# ------------------------------------------------------------
# 3. CALCULATE PERFORMANCE METRICS
# ------------------------------------------------------------

def evaluate_model(y_true, y_pred):
    return {
        "Accuracy (%)": accuracy_score(y_true, y_pred) * 100,
        "Macro Precision (%)": precision_score(
            y_true, y_pred, average="macro", zero_division=0
        ) * 100,
        "Macro Recall (%)": recall_score(
            y_true, y_pred, average="macro", zero_division=0
        ) * 100,
        "Macro F1 (%)": f1_score(
            y_true, y_pred, average="macro", zero_division=0
        ) * 100
    }

baseline_metrics = evaluate_model(
    actual_labels, baseline_predictions
)

experimental_metrics = evaluate_model(
    actual_labels, experimental_predictions
)

# ------------------------------------------------------------
# 4. CREATE THE COMPARISON TABLE
# ------------------------------------------------------------

comparison = pd.DataFrame([
    {
        "Model": "Baseline FT-Transformer",
        **baseline_metrics
    },
    {
        "Model": "Experimental FT-Transformer (Weighted Loss)",
        **experimental_metrics
    }
])

# Difference = experimental score minus baseline score
metric_columns = [
    "Accuracy (%)",
    "Macro Precision (%)",
    "Macro Recall (%)",
    "Macro F1 (%)"
]

improvement = {
    "Model": "Change (Experimental - Baseline)"
}

for column in metric_columns:
    improvement[column] = (
        experimental_metrics[column] - baseline_metrics[column]
    )

comparison = pd.concat(
    [comparison, pd.DataFrame([improvement])],
    ignore_index=True
)

# ------------------------------------------------------------
# 5. DISPLAY RESULTS — SAFE DISPLAY FUNCTION
# ------------------------------------------------------------

print("=" * 65)
print("BASELINE VS EXPERIMENTAL MODEL")
print("=" * 65)

show_table(comparison.round(4))

# ------------------------------------------------------------
# 6. SAVE THE COMPARISON TABLE
# ------------------------------------------------------------

comparison_path = (
    "FT_Transformer_Weighted_Loss_Comparison.csv"
)

comparison.to_csv(comparison_path, index=False)

print("\nComparison table saved to:", comparison_path)

# ------------------------------------------------------------
# 7. SHOW CLASS-WISE BASELINE RESULTS
# ------------------------------------------------------------

class_names = [
    str(name) for name in target_encoder.classes_
]

print("\n" + "=" * 65)
print("BASELINE FT-TRANSFORMER — CLASSIFICATION REPORT")
print("=" * 65)

print(classification_report(
    actual_labels,
    baseline_predictions,
    labels=np.arange(len(class_names)),
    target_names=class_names,
    digits=4,
    zero_division=0
))

# ------------------------------------------------------------
# 8. SHOW CLASS-WISE EXPERIMENTAL RESULTS
# ------------------------------------------------------------

print("\n" + "=" * 65)
print("EXPERIMENTAL FT-TRANSFORMER — CLASSIFICATION REPORT")
print("=" * 65)

print(classification_report(
    actual_labels,
    experimental_predictions,
    labels=np.arange(len(class_names)),
    target_names=class_names,
    digits=4,
    zero_division=0
))

# ------------------------------------------------------------
# 9. IDENTIFY WHETHER MACRO-F1 IMPROVED
# ------------------------------------------------------------

f1_change = (
    experimental_metrics["Macro F1 (%)"]
    - baseline_metrics["Macro F1 (%)"]
)

print("\n" + "=" * 65)
print("EXPERIMENTAL RESULT")
print("=" * 65)

if f1_change > 0:
    print(f"Macro-F1 improved by {f1_change:.4f} percentage points.")
elif f1_change < 0:
    print(f"Macro-F1 decreased by {abs(f1_change):.4f} percentage points.")
else:
    print("Macro-F1 remained unchanged.")

print(
    "\nNote: This experiment changes the class-weighting strategy. "
    "It does not guarantee improved performance."
)

