# STEP 10: Retrain a separate FT-Transformer with moderated class weights
# The original FT-Transformer remains unchanged.

import os
import copy
import time
import numpy as np
import pandas as pd
import torch
import torch.nn as nn

from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report
)

# 1. Check that all required variables are available
required_variables = [
    "trained_models",
    "train_loader",
    "val_loader",
    "test_loader",
    "predict_loader",
    "experimental_criterion",
    "DEVICE",
    "LEARNING_RATE",
    "target_encoder",
    "y_test"
]

missing = [
    name for name in required_variables
    if name not in globals()
]

if missing:
    raise RuntimeError(
        f"Missing variables: {missing}. "
        "Run the relevant earlier cells first."
    )

assert "FT-Transformer" in trained_models, (
    "The original FT-Transformer is not available."
)

# 2. Copy the original model so its weights are preserved
experimental_model = copy.deepcopy(
    trained_models["FT-Transformer"]
).to(DEVICE)

# A NEW optimizer is required for the experimental model
experimental_optimizer = torch.optim.AdamW(
    experimental_model.parameters(),
    lr=LEARNING_RATE,
    weight_decay=1e-4
)

best_val_f1 = -1.0
best_state = None
training_start = time.perf_counter()

# 3. Train using the experimental weighted loss
EXPERIMENTAL_EPOCHS = EPOCHS

print("========== EXPERIMENTAL FT-TRANSFORMER ==========")
print("Device:", DEVICE)
print("Epochs:", EXPERIMENTAL_EPOCHS)
print("Loss: moderated experimental class weights")

for epoch in range(EXPERIMENTAL_EPOCHS):
    experimental_model.train()
    total_loss = 0.0
    total_samples = 0

    for xn, xc, yb in train_loader:
        xn = xn.to(DEVICE, non_blocking=True)
        xc = xc.to(DEVICE, non_blocking=True)
        yb = yb.to(DEVICE, non_blocking=True)

        experimental_optimizer.zero_grad(set_to_none=True)

        with torch.autocast(
            device_type="cuda",
            dtype=torch.float16,
            enabled=(DEVICE.type == "cuda")
        ):
            logits = experimental_model(xn, xc)
            loss = experimental_criterion(logits, yb)

        loss.backward()
        torch.nn.utils.clip_grad_norm_(
            experimental_model.parameters(), 1.0
        )
        experimental_optimizer.step()

        total_loss += loss.item() * len(yb)
        total_samples += len(yb)

    # Select the best epoch using validation macro-F1
    val_probs_exp, val_labels_exp = predict_loader(
        experimental_model, val_loader
    )
    val_pred_exp = val_probs_exp.argmax(axis=1)

    val_macro_f1 = f1_score(
        val_labels_exp,
        val_pred_exp,
        average="macro",
        zero_division=0
    )

    mean_loss = total_loss / max(total_samples, 1)

    print(
        f"Epoch {epoch + 1}/{EXPERIMENTAL_EPOCHS} | "
        f"Loss: {mean_loss:.4f} | "
        f"Validation Macro-F1: {val_macro_f1:.4f}"
    )

    if val_macro_f1 > best_val_f1:
        best_val_f1 = val_macro_f1
        best_state = {
            key: value.detach().cpu().clone()
            for key, value in experimental_model.state_dict().items()
        }

# Restore the best validation checkpoint
if best_state is None:
    raise RuntimeError("No valid experimental checkpoint was created.")

experimental_model.load_state_dict(best_state)
experimental_model.to(DEVICE)

training_seconds = time.perf_counter() - training_start

# Save the experimental model separately
output_dir = "/content/AI_IDS_Final_Comparison"
os.makedirs(output_dir, exist_ok=True)

model_path = os.path.join(
    output_dir,
    "FT_Transformer_Moderated_Weights.pt"
)
torch.save(experimental_model.state_dict(), model_path)

print("\nExperimental training completed.")
print("Best validation Macro-F1:", round(best_val_f1, 4))
print("Training time (seconds):", round(training_seconds, 2))
print("Saved model:", model_path)

# 4. Evaluate the original and experimental models on the same test set
# The test set is used for final comparison, not epoch selection.

original_probs, original_labels = predict_loader(
    trained_models["FT-Transformer"], test_loader
)
experimental_probs, experimental_labels = predict_loader(
    experimental_model, test_loader
)

y_test_array = np.asarray(y_test).astype(int)

# Verify the labels and predictions are aligned
assert np.array_equal(original_labels, experimental_labels), (
    "Original and experimental test-label order differs."
)
assert np.array_equal(original_labels, y_test_array), (
    "Test labels do not align with y_test."
)

assert original_probs.shape == experimental_probs.shape, (
    "Original and experimental probability shapes differ."
)

original_pred = original_probs.argmax(axis=1)
experimental_pred = experimental_probs.argmax(axis=1)

class_names = [str(x) for x in target_encoder.classes_]

def calculate_metrics(y_true, y_pred, model_name):
    return {
        "Model": model_name,
        "Accuracy (%)": 100 * accuracy_score(y_true, y_pred),
        "Macro Precision (%)": 100 * precision_score(
            y_true, y_pred, average="macro", zero_division=0
        ),
        "Macro Recall (%)": 100 * recall_score(
            y_true, y_pred, average="macro", zero_division=0
        ),
        "Macro F1 (%)": 100 * f1_score(
            y_true, y_pred, average="macro", zero_division=0
        )
    }

comparison = pd.DataFrame([
    calculate_metrics(
        original_labels, original_pred,
        "Original FT-Transformer"
    ),
    calculate_metrics(
        experimental_labels, experimental_pred,
        "FT-Transformer - Moderated Weights"
    )
])

print("\n========== TEST-SET COMPARISON ==========")
print(comparison.round(3).to_string(index=False))

comparison_path = os.path.join(
    output_dir,
    "FT_Transformer_Weighted_Loss_Comparison.csv"
)
comparison.to_csv(comparison_path, index=False)

# 5. Show the change in macro-F1
original_f1 = comparison.loc[
    comparison["Model"] == "Original FT-Transformer",
    "Macro F1 (%)"
].iloc[0]

experimental_f1 = comparison.loc[
    comparison["Model"] == "FT-Transformer - Moderated Weights",
    "Macro F1 (%)"
].iloc[0]

print(
    "\nMacro-F1 change (percentage points):",
    round(experimental_f1 - original_f1, 3)
)

# 6. Save class-wise report for minority-class analysis
report = classification_report(
    experimental_labels,
    experimental_pred,
    labels=np.arange(len(class_names)),
    target_names=class_names,
    output_dict=True,
    zero_division=0
)

class_report_exp = pd.DataFrame(report).T
class_report_exp = class_report_exp.loc[
    class_names, ["precision", "recall", "f1-score", "support"]
]

class_report_exp = class_report_exp.rename(columns={
    "precision": "Precision",
    "recall": "Recall",
    "f1-score": "F1-score",
    "support": "Test Samples"
})

class_report_exp[["Precision", "Recall", "F1-score"]] *= 100
class_report_exp = class_report_exp.round(2)

print("\n========== EXPERIMENTAL CLASS-WISE RESULTS (%) ==========")
print(class_report_exp.to_string())

class_report_exp.to_csv(
    os.path.join(
        output_dir,
        "FT_Transformer_Moderated_Weights_Classwise.csv"
    )
)

print("\nSaved comparison:", comparison_path)
print("Saved class-wise report.")

# ============================================================
# STEP 12: COMPLETE CLASS-WISE COMPARISON
# Original FT-Transformer vs Moderated Class Weights
# ============================================================

import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import torch

from IPython.display import display as show_table
from sklearn.metrics import classification_report

# -----------------------------
# 1. Check required variables
# -----------------------------
required_variables = [
    "trained_models",
    "experimental_model",
    "test_loader",
    "predict_loader",
    "target_encoder"
]

missing = [name for name in required_variables if name not in globals()]

if missing:
    raise NameError(
        f"Missing variables: {missing}. "
        "Run the earlier model-training cells first."
    )

output_dir = "/content/AI_IDS_Final_Comparison"
os.makedirs(output_dir, exist_ok=True)

original_model = trained_models["FT-Transformer"]

# -----------------------------
# 2. Generate predictions
# -----------------------------
print("Generating original model predictions...")

original_probs, original_labels = predict_loader(
    original_model, test_loader
)

print("Generating experimental model predictions...")

experimental_probs, experimental_labels = predict_loader(
    experimental_model, test_loader
)

# Convert results to NumPy arrays
y_original = np.asarray(original_labels).astype(int).reshape(-1)
y_experimental = np.asarray(experimental_labels).astype(int).reshape(-1)

original_probs = np.asarray(original_probs)
experimental_probs = np.asarray(experimental_probs)

# Ensure the same test examples and label order
if not np.array_equal(y_original, y_experimental):
    raise ValueError(
        "The original and experimental labels do not match. "
        "Check the test_loader and prediction function."
    )

y_true = y_original
pred_original = original_probs.argmax(axis=1)
pred_experimental = experimental_probs.argmax(axis=1)

if len(y_true) != len(pred_original) or len(y_true) != len(pred_experimental):
    raise ValueError("Prediction count does not match the test labels.")

# -----------------------------
# 3. Obtain class names
# -----------------------------
class_names = list(target_encoder.classes_)
num_classes = len(class_names)

if (
    len(np.unique(y_true)) > num_classes
    or pred_original.max() >= num_classes
    or pred_experimental.max() >= num_classes
):
    raise ValueError("Class IDs do not match target_encoder.classes_.")

class_ids = list(range(num_classes))

# -----------------------------
# 4. Calculate classification reports
# -----------------------------
original_report = classification_report(
    y_true,
    pred_original,
    labels=class_ids,
    target_names=class_names,
    output_dict=True,
    zero_division=0
)

experimental_report = classification_report(
    y_true,
    pred_experimental,
    labels=class_ids,
    target_names=class_names,
    output_dict=True,
    zero_division=0
)

# -----------------------------
# 5. Build comparison table
# -----------------------------
rows = []

for class_name in class_names:
    old = original_report[class_name]
    new = experimental_report[class_name]

    rows.append({
        "Class": class_name,
        "Test Samples": int(old["support"]),
        "Original Precision (%)": old["precision"] * 100,
        "Experimental Precision (%)": new["precision"] * 100,
        "Precision Change (points)": (
            new["precision"] - old["precision"]
        ) * 100,
        "Original Recall (%)": old["recall"] * 100,
        "Experimental Recall (%)": new["recall"] * 100,
        "Recall Change (points)": (
            new["recall"] - old["recall"]
        ) * 100,
        "Original F1 (%)": old["f1-score"] * 100,
        "Experimental F1 (%)": new["f1-score"] * 100,
        "F1 Change (points)": (
            new["f1-score"] - old["f1-score"]
        ) * 100
    })

comparison = pd.DataFrame(rows).round(2)

print("\n" + "=" * 75)
print("CLASS-WISE COMPARISON")
print("=" * 75)

