import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import confusion_matrix, classification_report

# Output folder
OUT_DIR = "/content/AI_IDS_Final_Comparison"
os.makedirs(OUT_DIR, exist_ok=True)

# Convert labels and predictions to class indices if needed
y_true = np.asarray(test_labels)
y_pred = np.asarray(test_pred)

if y_true.ndim > 1:
    y_true = y_true.argmax(axis=1)
if y_pred.ndim > 1:
    y_pred = y_pred.argmax(axis=1)

y_true = y_true.astype(int).ravel()
y_pred = y_pred.astype(int).ravel()

# Build confusion matrix
n_classes = len(class_names)
labels = list(range(n_classes))

cm = confusion_matrix(y_true, y_pred, labels=labels)

# Save raw-count matrix
cm_df = pd.DataFrame(
    cm,
    index=class_names,
    columns=class_names
)
cm_df.to_csv(f"{OUT_DIR}/FT_Transformer_Weighted_Confusion_Matrix.csv")

plt.figure(figsize=(12, 9))
sns.heatmap(
    cm_df, annot=True, fmt="d", cmap="Blues",
    xticklabels=class_names, yticklabels=class_names
)
plt.title("FT-Transformer — Weighted Checkpoint Confusion Matrix")
plt.xlabel("Predicted Attack Class")
plt.ylabel("Actual Attack Class")
plt.xticks(rotation=45, ha="right")
plt.yticks(rotation=0)
plt.tight_layout()
plt.savefig(
    f"{OUT_DIR}/FT_Transformer_Weighted_Confusion_Matrix.png",
    dpi=300, bbox_inches="tight"
)
plt.show()

# Row-normalized matrix: percentage detected for each actual class
row_sums = cm.sum(axis=1, keepdims=True)
cm_norm = np.divide(
    cm, row_sums,
    out=np.zeros_like(cm, dtype=float),
    where=row_sums != 0
)

cm_norm_df = pd.DataFrame(
    cm_norm,
    index=class_names,
    columns=class_names
)
cm_norm_df.to_csv(
    f"{OUT_DIR}/FT_Transformer_Weighted_Confusion_Matrix_Normalized.csv"
)

plt.figure(figsize=(12, 9))
sns.heatmap(
    cm_norm_df * 100, annot=True, fmt=".1f",
    cmap="Blues", vmin=0, vmax=100
)
plt.title("FT-Transformer — Per-Class Detection Rate (%)")
plt.xlabel("Predicted Attack Class")
plt.ylabel("Actual Attack Class")
plt.xticks(rotation=45, ha="right")
plt.yticks(rotation=0)
plt.tight_layout()
plt.savefig(
    f"{OUT_DIR}/FT_Transformer_Weighted_Confusion_Matrix_Normalized.png",
    dpi=300, bbox_inches="tight"
)
plt.show()

print("Saved confusion matrices to:", OUT_DIR)
print("\nClassification report:")
print(classification_report(
    y_true, y_pred,
    labels=labels,
    target_names=[str(c) for c in class_names],
    digits=4,
    zero_division=0
))

import numpy as np
from sklearn.metrics import confusion_matrix

y_true = np.asarray(test_labels)
y_pred = np.asarray(test_pred)

if y_true.ndim > 1:
    y_true = y_true.argmax(axis=1)
if y_pred.ndim > 1:
    y_pred = y_pred.argmax(axis=1)

y_true = y_true.astype(int).ravel()
y_pred = y_pred.astype(int).ravel()

# Identify the Normal class
normal_idx = next(
    i for i, name in enumerate(class_names)
    if str(name).strip().lower() == "normal"
)

# Convert ten-class predictions into Normal vs Attack
actual_normal = (y_true == normal_idx)
predicted_normal = (y_pred == normal_idx)

# False alarm: actual Normal, predicted Attack
FP = np.sum(actual_normal & ~predicted_normal)

# Correctly recognized Normal traffic
TN = np.sum(actual_normal & predicted_normal)

FAR = (FP / (FP + TN) * 100) if (FP + TN) else 0.0

print("FT-Transformer False Alarm Evaluation")
print("-------------------------------------")
print(f"False alarms (FP): {FP}")
print(f"Correctly identified normal traffic (TN): {TN}")
print(f"False Alarm Rate (FAR): {FAR:.2f}%")

