import pandas as pd
import numpy as np

# Identify the target column
target_col = next(
    c for c in train_df.columns
    if c.strip().lower() == "attack_cat"
)

# Use common features, excluding targets and identifiers
excluded = {"attack_cat", "attack category", "target", "label", "id"}
audit_features = [
    c for c in train_df.columns
    if c in test_df.columns and c.strip().lower() not in excluded
]

# Hash each feature row, without using its label
train_audit = pd.DataFrame({
    "row_hash": pd.util.hash_pandas_object(
        train_df[audit_features], index=False
    ).values,
    "label": train_df[target_col].astype(str).values
})

test_audit = pd.DataFrame({
    "row_hash": pd.util.hash_pandas_object(
        test_df[audit_features], index=False
    ).values,
    "label": test_df[target_col].astype(str).values
})

# For each unique feature hash, collect all labels found
train_groups = (
    train_audit.groupby("row_hash")["label"]
    .agg(lambda s: sorted(set(s)))
    .reset_index(name="train_labels")
)

test_groups = (
    test_audit.groupby("row_hash")["label"]
    .agg(lambda s: sorted(set(s)))
    .reset_index(name="test_labels")
)

common = train_groups.merge(test_groups, on="row_hash", how="inner")

# Separate unambiguous hashes from hashes with multiple labels
train_single = common["train_labels"].apply(len).eq(1)
test_single = common["test_labels"].apply(len).eq(1)

unambiguous = common[train_single & test_single].copy()
unambiguous["same_label"] = unambiguous.apply(
    lambda r: r["train_labels"][0] == r["test_labels"][0],
    axis=1
)

print("=== UNIQUE FEATURE-HASH AUDIT ===")
print("Unique feature hashes in training:", len(train_groups))
print("Unique feature hashes in testing:", len(test_groups))
print("Unique hashes shared across both:", len(common))
print("Shared hashes with one label per split:", len(unambiguous))
print("Same label in both splits:",
      int(unambiguous["same_label"].sum()))
print("Different labels across splits:",
      int((~unambiguous["same_label"]).sum()))
print("Multiple labels within training for shared hashes:",
      int((~train_single).sum()))
print("Multiple labels within testing for shared hashes:",
      int((~test_single).sum()))

print("\n=== EXAMPLES OF UNAMBIGUOUS LABEL CONFLICTS ===")
conflicts = unambiguous[~unambiguous["same_label"]]
display(conflicts.head(20))

# Inspect one conflicting feature hash
if len(conflicts) == 0:
    print("No unambiguous conflicts available to inspect.")
else:
    example_hash = conflicts.iloc[0]["row_hash"]

    train_rows = train_audit[
        train_audit["row_hash"] == example_hash
    ]
    test_rows = test_audit[
        test_audit["row_hash"] == example_hash
    ]

    train_original = train_df.loc[
        train_audit["row_hash"] == example_hash,
        audit_features + [target_col]
    ]

    test_original = test_df.loc[
        test_audit["row_hash"] == example_hash,
        audit_features + [target_col]
    ]

    print("Feature hash:", example_hash)
    print("\nTraining record:")
    display(train_original.head(3))

    print("\nTesting record:")
    display(test_original.head(3))

    print("\nLabels in training:", train_rows["label"].unique())
    print("Labels in testing:", test_rows["label"].unique())

# Summarize labels for every feature hash shared across train and test

shared_hashes = set(train_groups["row_hash"]) & set(test_groups["row_hash"])

train_shared = train_audit[
    train_audit["row_hash"].isin(shared_hashes)
]
test_shared = test_audit[
    test_audit["row_hash"].isin(shared_hashes)
]

print("Training rows with shared feature hashes:", len(train_shared))
print("Testing rows with shared feature hashes:", len(test_shared))

print("\nTraining label counts among shared-feature rows:")
display(train_shared["label"].value_counts().to_frame("count"))

print("\nTesting label counts among shared-feature rows:")
display(test_shared["label"].value_counts().to_frame("count"))

# Inspect label combinations for shared hashes
train_label_sets = (
    train_shared.groupby("row_hash")["label"]
    .agg(lambda s: tuple(sorted(set(s))))
    .rename("train_labels")
)
test_label_sets = (
    test_shared.groupby("row_hash")["label"]
    .agg(lambda s: tuple(sorted(set(s))))
    .rename("test_labels")
)

shared_summary = pd.concat(
    [train_label_sets, test_label_sets], axis=1, join="inner"
).reset_index()

print("\nMost frequent train/test label-set combinations:")
display(
    shared_summary.groupby(
        ["train_labels", "test_labels"], dropna=False
    ).size().sort_values(ascending=False).head(20).to_frame("hash_count")
)

# Check feature overlap between internal training and validation subsets.
# This uses the existing train_idx and val_idx.

internal_train_df = train_df.iloc[train_idx]
internal_val_df = train_df.iloc[val_idx]

train_hashes = pd.util.hash_pandas_object(
    internal_train_df[audit_features], index=False
)
val_hashes = pd.util.hash_pandas_object(
    internal_val_df[audit_features], index=False
)

train_hash_set = set(train_hashes)
val_hash_set = set(val_hashes)
shared_internal = train_hash_set & val_hash_set

print("Internal training rows:", len(internal_train_df))
print("Internal validation rows:", len(internal_val_df))
print("Unique feature hashes shared across both:", len(shared_internal))
print(
    "Percentage of validation rows whose feature hash occurs in training:",
    round(100 * val_hashes.isin(train_hash_set).mean(), 2), "%"
)

# Check whether the scaler was fitted before the internal split
print("\nScaler samples seen during fitting:",
      getattr(scaler, "n_samples_seen_", "Not available"))
print("Internal training subset size:", len(internal_train_df))

