import torch
from torch.utils.data import TensorDataset, DataLoader

# Use the corrected numerical features
xn_train_clean = torch.tensor(X_train_num_clean, dtype=torch.float32)
xn_val_clean = torch.tensor(X_val_num_clean, dtype=torch.float32)
xn_test_clean = torch.tensor(X_test_num_clean, dtype=torch.float32)

# Encode the 3 categorical columns as integer IDs.
# Fit category mappings on the new training subset only.
cat_maps_clean = {}
X_train_cat_ids = np.zeros(
    (len(X_train_raw), len(cat_cols_clean)), dtype=np.int64
)
X_val_cat_ids = np.zeros(
    (len(X_val_raw), len(cat_cols_clean)), dtype=np.int64
)
X_test_cat_ids = np.zeros(
    (len(X_test_raw), len(cat_cols_clean)), dtype=np.int64
)

for j, col in enumerate(cat_cols_clean):
    train_values = X_train_raw[col].fillna("__MISSING__").astype(str)
    val_values = X_val_raw[col].fillna("__MISSING__").astype(str)
    test_values = X_test_raw[col].fillna("__MISSING__").astype(str)

    # ID 0 is reserved for unknown categories
    categories = sorted(train_values.unique())
    mapping = {value: idx + 1 for idx, value in enumerate(categories)}
    cat_maps_clean[col] = mapping

    X_train_cat_ids[:, j] = train_values.map(mapping).fillna(0).to_numpy()
    X_val_cat_ids[:, j] = val_values.map(mapping).fillna(0).to_numpy()
    X_test_cat_ids[:, j] = test_values.map(mapping).fillna(0).to_numpy()

xc_train_clean = torch.tensor(X_train_cat_ids, dtype=torch.long)
xc_val_clean = torch.tensor(X_val_cat_ids, dtype=torch.long)
xc_test_clean = torch.tensor(X_test_cat_ids, dtype=torch.long)

yt_train_clean = torch.tensor(y_train_clean, dtype=torch.long)
yt_val_clean = torch.tensor(y_val_clean, dtype=torch.long)
yt_test_clean = torch.tensor(y_test_clean, dtype=torch.long)

# Build datasets
train_dataset_clean = TensorDataset(
    xn_train_clean, xc_train_clean, yt_train_clean
)
val_dataset_clean = TensorDataset(
    xn_val_clean, xc_val_clean, yt_val_clean
)
test_dataset_clean = TensorDataset(
    xn_test_clean, xc_test_clean, yt_test_clean
)

BATCH_SIZE_CLEAN = 512

train_loader_clean = DataLoader(
    train_dataset_clean, batch_size=BATCH_SIZE_CLEAN, shuffle=True
)
val_loader_clean = DataLoader(
    val_dataset_clean, batch_size=BATCH_SIZE_CLEAN, shuffle=False
)
test_loader_clean = DataLoader(
    test_dataset_clean, batch_size=BATCH_SIZE_CLEAN, shuffle=False
)

print("Train batches:", len(train_loader_clean))
print("Validation batches:", len(val_loader_clean))
print("Test batches:", len(test_loader_clean))
print("Numerical input shape:", tuple(xn_train_clean.shape))
print("Categorical input shape:", tuple(xc_train_clean.shape))
print("Categorical embedding sizes:",
      [len(cat_maps_clean[c]) + 1 for c in cat_cols_clean])
print("Classes:", num_classes_clean)

# Verify one batch
batch_xn, batch_xc, batch_y = next(iter(train_loader_clean))
print("\nBatch numerical shape:", tuple(batch_xn.shape))
print("Batch categorical shape:", tuple(batch_xc.shape))
print("Batch label shape:", tuple(batch_y.shape))

