import copy
import numpy as np
import torch
import torch.nn as nn
from sklearn.metrics import accuracy_score, f1_score

# 1. Verify the expected model configuration
assert len(cat_cols_clean) == 3
assert len(class_names_clean) == 10

# Save current global settings so we can restore them afterward
old_cat_cardinalities = CAT_CARDINALITIES
old_num_features = NUM_FEATURES
old_num_classes = NUM_CLASSES

# Configure the model for our corrected inputs
CAT_CARDINALITIES = [len(cat_maps_clean[c]) + 1 for c in cat_cols_clean]
NUM_FEATURES = X_train_num_clean.shape[1]
NUM_CLASSES = num_classes_clean

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

# 2. Create a fresh model with the corrected embedding sizes
ft_clean = FTTransformerClass().to(device)

# 3. Weighted loss and optimizer
weight_tensor = torch.tensor(
    class_weights_clean, dtype=torch.float32, device=device
)

criterion_clean = nn.CrossEntropyLoss(weight=weight_tensor)
optimizer_clean = torch.optim.AdamW(
    ft_clean.parameters(), lr=1e-3, weight_decay=1e-4
)

# 4. Training loop with validation macro-F1 checkpoint selection
EPOCHS_CLEAN = 20
PATIENCE_CLEAN = 4
best_val_macro_f1 = -1.0
best_state_clean = None
epochs_without_improvement = 0
history_clean = []

for epoch in range(1, EPOCHS_CLEAN + 1):
    ft_clean.train()
    running_loss = 0.0
    seen = 0

    for xn, xc, yb in train_loader_clean:
        xn = xn.to(device)
        xc = xc.to(device)
        yb = yb.to(device)

        optimizer_clean.zero_grad(set_to_none=True)
        logits = ft_clean(xn, xc)
        loss = criterion_clean(logits, yb)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(ft_clean.parameters(), 1.0)
        optimizer_clean.step()

        running_loss += loss.item() * len(yb)
        seen += len(yb)

    # Validation only; do not use the official test set here
    ft_clean.eval()
    val_true, val_pred = [], []

    with torch.no_grad():
        for xn, xc, yb in val_loader_clean:
            logits = ft_clean(xn.to(device), xc.to(device))
            preds = logits.argmax(dim=1).cpu().numpy()
            val_pred.extend(preds)
            val_true.extend(yb.numpy())

    val_acc = accuracy_score(val_true, val_pred)
    val_macro_f1 = f1_score(
        val_true, val_pred, average="macro", zero_division=0
    )

    epoch_loss = running_loss / seen
    history_clean.append({
        "epoch": epoch,
        "train_loss": epoch_loss,
        "val_accuracy": val_acc,
        "val_macro_f1": val_macro_f1
    })

    print(
        f"Epoch {epoch:02d}/{EPOCHS_CLEAN} | "
        f"Loss: {epoch_loss:.4f} | "
        f"Val accuracy: {val_acc:.4f} | "
        f"Val macro-F1: {val_macro_f1:.4f}"
    )

    if val_macro_f1 > best_val_macro_f1:
        best_val_macro_f1 = val_macro_f1
        best_state_clean = copy.deepcopy(ft_clean.state_dict())
        epochs_without_improvement = 0
    else:
        epochs_without_improvement += 1

    if epochs_without_improvement >= PATIENCE_CLEAN:
        print("Early stopping: validation macro-F1 did not improve.")
        break

# Restore the best validation checkpoint
if best_state_clean is None:
    raise RuntimeError("No model checkpoint was saved.")

ft_clean.load_state_dict(best_state_clean)
ft_clean.eval()

print("\nTraining complete.")
print("Best validation macro-F1:", round(best_val_macro_f1, 4))
print("Device:", device)
print("Best model stored in variable: ft_clean")

import numpy as np
import torch
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report,
    confusion_matrix
)

# Evaluate the best FT-Transformer checkpoint
ft_clean.eval()

y_true = []
y_pred = []

with torch.no_grad():
    for xn, xc, y in test_loader_clean:
        xn = xn.to(device)
        xc = xc.to(device)

        logits = ft_clean(xn, xc)
        predictions = torch.argmax(logits, dim=1)

        y_true.extend(y.cpu().numpy())
        y_pred.extend(predictions.cpu().numpy())

y_true = np.asarray(y_true)
y_pred = np.asarray(y_pred)

# Overall test metrics
print("=" * 60)
print("FT-TRANSFORMER: OFFICIAL UNSW-NB15 TEST RESULTS")
print("=" * 60)

print(f"Test Accuracy : {accuracy_score(y_true, y_pred):.4f}")
print(f"Macro Precision: {precision_score(y_true, y_pred, average='macro', zero_division=0):.4f}")
print(f"Macro Recall   : {recall_score(y_true, y_pred, average='macro', zero_division=0):.4f}")
print(f"Macro F1-score : {f1_score(y_true, y_pred, average='macro', zero_division=0):.4f}")
print(f"Weighted F1    : {f1_score(y_true, y_pred, average='weighted', zero_division=0):.4f}")

# Detailed metrics for all 10 classes
print("\nCLASSIFICATION REPORT")
print(classification_report(
    y_true,
    y_pred,
    labels=np.arange(len(class_names_clean)),
    target_names=list(class_names_clean),
    zero_division=0,
    digits=4
))

# Normal-class false-alarm rate
normal_matches = np.where(
    np.asarray(class_names_clean) == "Normal"
)[0]

if len(normal_matches) == 1:
    normal_id = int(normal_matches[0])
    actual_normal = (y_true == normal_id)
    false_alarms = actual_normal & (y_pred != normal_id)

    if actual_normal.sum() > 0:
        far = false_alarms.sum() / actual_normal.sum()
        print(f"\nNormal-class False Alarm Rate: {far:.4f} ({far:.2%})")
    else:
        print("\nFAR not calculated: no Normal samples in test set.")
else:
    print("\nFAR not calculated: Normal class was not identified uniquely.")

# Save confusion matrix for plotting in the next step
cm_ft_clean = confusion_matrix(
    y_true,
    y_pred,
    labels=np.arange(len(class_names_clean))
)

print("\nConfusion matrix shape:", cm_ft_clean.shape)
print("Evaluation complete.")

