import copy
import numpy as np
import torch
import torch.nn as nn
from sklearn.metrics import accuracy_score, f1_score

# Standard balanced weights, without the square-root adjustment
counts = np.bincount(y_train_clean, minlength=num_classes_clean)
balanced_weights_exp2 = len(y_train_clean) / (
    num_classes_clean * np.maximum(counts, 1)
)

# Normalize weights to mean 1 for easier comparison
balanced_weights_exp2 = (
    balanced_weights_exp2 / balanced_weights_exp2.mean()
)

print("New class weights:")
for name, weight in zip(class_names_clean, balanced_weights_exp2):
    print(f"{name:18s}: {weight:.4f}")

# Build a separate model; keep ft_clean unchanged
ft_exp2 = FTTransformerClass().to(device)

criterion_exp2 = nn.CrossEntropyLoss(
    weight=torch.tensor(
        balanced_weights_exp2,
        dtype=torch.float32,
        device=device
    )
)

optimizer_exp2 = torch.optim.AdamW(
    ft_exp2.parameters(),
    lr=1e-3,
    weight_decay=1e-4
)

best_val_f1_exp2 = -1.0
best_state_exp2 = None
patience_exp2 = 4
stale_exp2 = 0
max_epochs_exp2 = 20

for epoch in range(max_epochs_exp2):
    ft_exp2.train()
    running_loss = 0.0

    for xn, xc, y in train_loader_clean:
        xn, xc, y = xn.to(device), xc.to(device), y.to(device)

        optimizer_exp2.zero_grad()
        logits = ft_exp2(xn, xc)
        loss = criterion_exp2(logits, y)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(ft_exp2.parameters(), 1.0)
        optimizer_exp2.step()

        running_loss += loss.item()

    # Validation only; do not use the official test set here
    ft_exp2.eval()
    val_true_exp2, val_pred_exp2 = [], []

    with torch.no_grad():
        for xn, xc, y in val_loader_clean:
            logits = ft_exp2(xn.to(device), xc.to(device))
            val_pred_exp2.extend(logits.argmax(dim=1).cpu().numpy())
            val_true_exp2.extend(y.numpy())

    val_acc_exp2 = accuracy_score(val_true_exp2, val_pred_exp2)
    val_f1_exp2 = f1_score(
        val_true_exp2, val_pred_exp2,
        average="macro", zero_division=0
    )

    print(
        f"Epoch {epoch+1:02d}/{max_epochs_exp2} | "
        f"Loss: {running_loss/len(train_loader_clean):.4f} | "
        f"Val accuracy: {val_acc_exp2:.4f} | "
        f"Val macro-F1: {val_f1_exp2:.4f}"
    )

    if val_f1_exp2 > best_val_f1_exp2:
        best_val_f1_exp2 = val_f1_exp2
        best_state_exp2 = copy.deepcopy(ft_exp2.state_dict())
        stale_exp2 = 0
    else:
        stale_exp2 += 1

    if stale_exp2 >= patience_exp2:
        print("Early stopping.")
        break

ft_exp2.load_state_dict(best_state_exp2)
print("\nExperiment 2 training complete.")
print(f"Best validation macro-F1: {best_val_f1_exp2:.4f}")

import numpy as np
import pandas as pd
import torch
from sklearn.metrics import accuracy_score, f1_score

def collect_predictions(model, loader):
    model.eval()
    true_labels, predicted_labels = [], []

    with torch.no_grad():
        for xn, xc, y in loader:
            logits = model(xn.to(device), xc.to(device))
            true_labels.extend(y.numpy())
            predicted_labels.extend(logits.argmax(dim=1).cpu().numpy())

    return np.asarray(true_labels), np.asarray(predicted_labels)

# Validation predictions only
y_val_original, pred_val_original = collect_predictions(
    ft_clean, val_loader_clean
)
y_val_exp2, pred_val_exp2 = collect_predictions(
    ft_exp2, val_loader_clean
)

normal_id = list(class_names_clean).index("Normal")
fuzzers_id = list(class_names_clean).index("Fuzzers")

def validation_metrics(y, pred, name):
    normal_mask = y == normal_id
    far = np.mean(pred[normal_mask] != normal_id) if normal_mask.any() else np.nan
    normal_to_fuzzers = np.mean(
        pred[normal_mask] == fuzzers_id
    ) if normal_mask.any() else np.nan

    return {
        "Model": name,
        "Accuracy": accuracy_score(y, pred),
        "Macro_F1": f1_score(y, pred, average="macro", zero_division=0),
        "Normal_FAR": far,
        "Normal_predicted_as_Fuzzers": normal_to_fuzzers
    }

comparison = pd.DataFrame([
    validation_metrics(y_val_original, pred_val_original, "Original weights"),
    validation_metrics(y_val_exp2, pred_val_exp2, "Standard balanced weights")
])

print(comparison.to_string(index=False, float_format=lambda x: f"{x:.4f}"))

