import numpy as np
import pandas as pd
import torch

normal_id = list(class_names_clean).index("Normal")
fuzzers_id = list(class_names_clean).index("Fuzzers")

def collect_probabilities(model, loader):
    model.eval()
    all_probs = []
    all_labels = []

    with torch.no_grad():
        for xn, xc, y in loader:
            logits = model(xn.to(device), xc.to(device))
            probs = torch.softmax(logits, dim=1)

            all_probs.append(probs.cpu().numpy())
            all_labels.append(y.numpy())

    return np.concatenate(all_labels), np.concatenate(all_probs)

# Evaluate confidence on validation and official test
y_val_prob_labels, val_probs = collect_probabilities(
    ft_clean, val_loader_clean
)
y_test_prob_labels, test_probs = collect_probabilities(
    ft_clean, test_loader_clean
)

def normal_confidence_report(y, probs, split_name):
    mask = y == normal_id
    normal_probs = probs[mask, normal_id]
    predicted = probs[mask].argmax(axis=1)

    return {
        "Split": split_name,
        "Actual_Normal_Count": int(mask.sum()),
        "Mean_Normal_Probability": float(normal_probs.mean()),
        "Median_Normal_Probability": float(np.median(normal_probs)),
        "Normal_Prediction_Rate": float(np.mean(predicted == normal_id)),
        "Normal_to_Fuzzers_Rate": float(np.mean(predicted == fuzzers_id))
    }

confidence_df = pd.DataFrame([
    normal_confidence_report(y_val_prob_labels, val_probs, "Validation"),
    normal_confidence_report(y_test_prob_labels, test_probs, "Official test")
])

print(confidence_df.to_string(
    index=False,
    float_format=lambda x: f"{x:.4f}"
))

import numpy as np
import pandas as pd

normal_id = list(class_names_clean).index("Normal")

def normal_probability_bands(y, probs, split_name):
    mask = y == normal_id
    p = probs[mask, normal_id]

    rows = []
    for threshold in [0.10, 0.25, 0.50, 0.75, 0.90, 0.99]:
        rows.append({
            "Split": split_name,
            "Normal_probability_below": threshold,
            "Count": int((p < threshold).sum()),
            "Percentage": round(float((p < threshold).mean() * 100), 2)
        })

    return rows

rows = (
    normal_probability_bands(y_val_prob_labels, val_probs, "Validation")
    + normal_probability_bands(y_test_prob_labels, test_probs, "Official test")
)

print(pd.DataFrame(rows).to_string(index=False))

