import numpy as np
import pandas as pd
from sklearn.preprocessing import StandardScaler

# Features whose distributions we want to transform
timing_features = ["tcprtt", "synack", "ackdat"]

# Make independent copies; do not modify the original data
X_train_num_log = X_train_raw[num_cols_clean].copy()
X_val_num_log = X_val_raw[num_cols_clean].copy()
X_test_num_log = X_test_raw[num_cols_clean].copy()

# Ensure numerical values are valid and handle any missing values
for df in [X_train_num_log, X_val_num_log, X_test_num_log]:
    df.replace([np.inf, -np.inf], np.nan, inplace=True)
    df.fillna(0, inplace=True)

# Apply log1p to the selected nonnegative timing features
for feature in timing_features:
    if (
        (X_train_num_log[feature] < 0).any()
        or (X_val_num_log[feature] < 0).any()
        or (X_test_num_log[feature] < 0).any()
    ):
        raise ValueError(
            f"{feature} contains negative values; inspect before log1p."
        )

    for df in [X_train_num_log, X_val_num_log, X_test_num_log]:
        df[feature] = np.log1p(df[feature])

# Fit the new scaler on training data only
scaler_log = StandardScaler()

X_train_num_log = scaler_log.fit_transform(X_train_num_log).astype(np.float32)
X_val_num_log = scaler_log.transform(X_val_num_log).astype(np.float32)
X_test_num_log = scaler_log.transform(X_test_num_log).astype(np.float32)

print("Transformed feature shapes:")
print("Train:", X_train_num_log.shape)
print("Validation:", X_val_num_log.shape)
print("Test:", X_test_num_log.shape)

print("\nScaler fitted on training rows:", scaler_log.n_samples_seen_)
print("All transformed values finite:",
      np.isfinite(X_train_num_log).all()
      and np.isfinite(X_val_num_log).all()
      and np.isfinite(X_test_num_log).all())

import torch
from torch.utils.data import TensorDataset, DataLoader

# Convert transformed numerical features to tensors
xn_train_log = torch.tensor(X_train_num_log, dtype=torch.float32)
xn_val_log = torch.tensor(X_val_num_log, dtype=torch.float32)
xn_test_log = torch.tensor(X_test_num_log, dtype=torch.float32)

# Reuse existing categorical IDs and encoded labels
# These are already prepared in the original pipeline.
train_dataset_log = TensorDataset(
    xn_train_log,
    xc_train_clean.cpu(),
    torch.tensor(y_train_raw.map(
        {name: i for i, name in enumerate(label_encoder_clean.classes_)}
    ).to_numpy(), dtype=torch.long)
)

val_dataset_log = TensorDataset(
    xn_val_log,
    xc_val_clean.cpu(),
    torch.tensor(y_val_raw.map(
        {name: i for i, name in enumerate(label_encoder_clean.classes_)}
    ).to_numpy(), dtype=torch.long)
)

test_dataset_log = TensorDataset(
    xn_test_log,
    xc_test_clean.cpu(),
    torch.tensor(y_test_raw.map(
        {name: i for i, name in enumerate(label_encoder_clean.classes_)}
    ).to_numpy(), dtype=torch.long)
)

# Use the same batch size as the original loaders
train_loader_log = DataLoader(
    train_dataset_log, batch_size=512, shuffle=True
)
val_loader_log = DataLoader(
    val_dataset_log, batch_size=512, shuffle=False
)
test_loader_log = DataLoader(
    test_dataset_log, batch_size=512, shuffle=False
)

print("Train batches:", len(train_loader_log))
print("Validation batches:", len(val_loader_log))
print("Test batches:", len(test_loader_log))

# Verify one batch
xn, xc, yb = next(iter(train_loader_log))
print("\nNumerical batch shape:", xn.shape)
print("Categorical batch shape:", xc.shape)
print("Label batch shape:", yb.shape)
print("Labels valid:", int(yb.min()), "to", int(yb.max()))

