import copy
import numpy as np
import torch
import torch.nn as nn
from sklearn.metrics import f1_score, accuracy_score

# 1. Set random seeds
torch.manual_seed(42)
np.random.seed(42)

if torch.cuda.is_available():
    torch.cuda.manual_seed_all(42)

# 2. Check that required variables exist
required_variables = [
    "train_loader_log",
    "val_loader_log",
    "FTTransformerClass",
    "class_weights_clean",
    "device"
]

missing = [
    name for name in required_variables
    if name not in globals()
]

if missing:
    raise NameError(
        "Missing variables: " + ", ".join(missing)
        + ". Run the earlier data preparation cells first."
    )

# 3. Create a NEW model; preserve ft_clean
ft_log = FTTransformerClass().to(device)

# 4. Convert NumPy class weights to a PyTorch tensor
weights_log = torch.as_tensor(
    np.asarray(class_weights_clean),
    dtype=torch.float32,
    device=device
)

assert len(weights_log) == 10, (
    f"Expected 10 class weights, got {len(weights_log)}"
)

criterion_log = nn.CrossEntropyLoss(weight=weights_log)

# 5. Optimizer
optimizer_log = torch.optim.AdamW(
    ft_log.parameters(),
    lr=1e-3,
    weight_decay=1e-4
)

# 6. Training configuration
max_epochs = 20
patience = 4

best_val_f1_log = -1.0
best_epoch_log = 0
best_state_log = None
epochs_without_improvement = 0

# 7. Train and select the best checkpoint using validation macro-F1
for epoch in range(1, max_epochs + 1):

    ft_log.train()
    total_loss = 0.0
    total_rows = 0

    for xn, xc, yb in train_loader_log:

        xn = xn.to(device)
        xc = xc.to(device)
        yb = yb.to(device)

        optimizer_log.zero_grad(set_to_none=True)

        logits = ft_log(xn, xc)
        loss = criterion_log(logits, yb)

        loss.backward()
        torch.nn.utils.clip_grad_norm_(
            ft_log.parameters(), max_norm=1.0
        )
        optimizer_log.step()

        total_loss += loss.item() * len(yb)
        total_rows += len(yb)

    train_loss = total_loss / total_rows

    # Validation only: do not evaluate the official test set here
    ft_log.eval()
    val_true_epoch = []
    val_pred_epoch = []

    with torch.no_grad():
        for xn, xc, yb in val_loader_log:

            xn = xn.to(device)
            xc = xc.to(device)

            logits = ft_log(xn, xc)
            predictions = logits.argmax(dim=1).cpu().numpy()

            val_pred_epoch.extend(predictions)
            val_true_epoch.extend(yb.cpu().numpy())

    val_f1 = f1_score(
        val_true_epoch,
        val_pred_epoch,
        labels=np.arange(10),
        average="macro",
        zero_division=0
    )

    val_acc = accuracy_score(
        val_true_epoch, val_pred_epoch
    )

    print(
        f"Epoch {epoch:02d}/{max_epochs} | "
        f"Loss: {train_loss:.4f} | "
        f"Val Accuracy: {val_acc:.4f} | "
        f"Val Macro-F1: {val_f1:.4f}"
    )

    if val_f1 > best_val_f1_log:
        best_val_f1_log = val_f1
        best_epoch_log = epoch
        best_state_log = copy.deepcopy(ft_log.state_dict())
        epochs_without_improvement = 0
    else:
        epochs_without_improvement += 1

    if epochs_without_improvement >= patience:
        print("Early stopping triggered.")
        break

# 8. Restore the best validation checkpoint
if best_state_log is None:
    raise RuntimeError("Training did not produce a valid checkpoint.")

ft_log.load_state_dict(best_state_log)
ft_log.eval()

print("\nTraining complete.")
print("Best epoch:", best_epoch_log)
print(f"Best validation macro-F1: {best_val_f1_log:.4f}")
print("Original baseline validation macro-F1: 0.5849")
print("Original ft_clean model was not modified.")

import numpy as np
import torch
from sklearn.metrics import f1_score, accuracy_score, classification_report

normal_id = list(label_encoder_clean.classes_).index("Normal")
fuzzers_id = list(label_encoder_clean.classes_).index("Fuzzers")

def get_predictions(model, loader):
    model.eval()
    true_labels = []
    predicted_labels = []

    with torch.no_grad():
        for xn, xc, yb in loader:
            xn = xn.to(device)
            xc = xc.to(device)

            pred = model(xn, xc).argmax(dim=1).cpu().numpy()

            true_labels.extend(yb.cpu().numpy())
            predicted_labels.extend(pred)

    return np.asarray(true_labels), np.asarray(predicted_labels)

# Both models evaluated on the same validation labels
y_val_original, pred_val_original = get_predictions(
    ft_clean, val_loader_clean
)

y_val_log, pred_val_log = get_predictions(
    ft_log, val_loader_log
)

def calculate_metrics(y_true, y_pred, model_name):
    actual_normal = (y_true == normal_id)
    correct_normal = actual_normal & (y_pred == normal_id)
    normal_as_fuzzers = actual_normal & (y_pred == fuzzers_id)

    normal_far = 1 - (
        correct_normal.sum() / max(actual_normal.sum(), 1)
    )

    return {
        "Model": model_name,
        "Accuracy": accuracy_score(y_true, y_pred),
        "Macro_F1": f1_score(
            y_true, y_pred, average="macro", zero_division=0
        ),
        "Normal_FAR": normal_far,
        "Normal_to_Fuzzers_percent": (
            100 * normal_as_fuzzers.sum()
            / max(actual_normal.sum(), 1)
        )
    }

comparison = [
    calculate_metrics(
        y_val_original, pred_val_original, "Original FT-Transformer"
    ),
    calculate_metrics(
        y_val_log, pred_val_log, "Log-transformed FT-Transformer"
    )
]

import pandas as pd
print(pd.DataFrame(comparison).round(4).to_string(index=False))

