import numpy as np
import matplotlib.pyplot as plt
from sklearn.preprocessing import label_binarize
from sklearn.metrics import roc_curve, auc
import torch

def get_probabilities(model, loader):
    model.eval()
    all_probs, all_labels = [], []

    with torch.no_grad():
        for xn, xc, yb in loader:
            xn = xn.to(device)
            xc = xc.to(device)

            probs = torch.softmax(model(xn, xc), dim=1)
            all_probs.append(probs.cpu().numpy())
            all_labels.append(yb.cpu().numpy())

    return np.concatenate(all_labels), np.concatenate(all_probs)

# Validation probabilities
y_true_orig, probs_orig = get_probabilities(
    ft_clean, val_loader_clean
)
y_true_log, probs_log = get_probabilities(
    ft_log, val_loader_log
)

class_names = list(label_encoder_clean.classes_)
class_ids = np.arange(len(class_names))

y_bin_orig = label_binarize(y_true_orig, classes=class_ids)
y_bin_log = label_binarize(y_true_log, classes=class_ids)

# Dark theme
fig, ax = plt.subplots(figsize=(11, 8))
fig.patch.set_facecolor("#10111B")
ax.set_facecolor("#10111B")

models = [
    (y_bin_orig, probs_orig, "Original FT-Transformer", "#00E5FF"),
    (y_bin_log, probs_log, "Log-Transformed FT-Transformer", "#FF6B6B")
]

for y_bin, probs, name, color in models:
    valid_classes = [
        i for i in class_ids
        if np.unique(y_bin[:, i]).size == 2
    ]

    mean_fpr = np.linspace(0, 1, 501)
    mean_tpr = np.zeros_like(mean_fpr)

    for i in valid_classes:
        fpr, tpr, _ = roc_curve(y_bin[:, i], probs[:, i])
        mean_tpr += np.interp(mean_fpr, fpr, tpr)

    mean_tpr /= len(valid_classes)
    macro_auc = auc(mean_fpr, mean_tpr)

    ax.plot(
        mean_fpr, mean_tpr,
        color=color,
        linewidth=3,
        label=f"{name} (AUC = {macro_auc:.4f})"
    )

# Random classifier reference
ax.plot(
    [0, 1], [0, 1],
    color="#FFD166",
    linestyle="--",
    linewidth=2,
    label="Random Classifier"
)

# Add subtle filled areas under the curves
ax.fill_between(
    mean_fpr, mean_tpr, alpha=0.05, color="#A78BFA"
)

ax.set_title(
    "Macro-Average ROC Curve — Validation",
    color="white", fontsize=16, fontweight="bold", pad=18
)
ax.set_xlabel("False Positive Rate", color="white", fontsize=12)
ax.set_ylabel("True Positive Rate", color="white", fontsize=12)

ax.set_xlim(0, 1)
ax.set_ylim(0, 1.02)
ax.set_xticks(np.arange(0, 1.01, 0.1))
ax.set_yticks(np.arange(0, 1.01, 0.1))
ax.tick_params(colors="#E5E7EB")
ax.grid(color="#9CA3AF", alpha=0.18, linestyle=":")

ax.legend(
    loc="lower right",
    facecolor="#202334",
    edgecolor="#555A70",
    labelcolor="white",
    fontsize=9
)

for spine in ax.spines.values():
    spine.set_color("#555A70")

plt.tight_layout()
plt.show()

