import numpy as np
import matplotlib.pyplot as plt
from sklearn.preprocessing import label_binarize
from sklearn.metrics import precision_recall_curve, average_precision_score

# Use the validation probabilities already collected
class_names = list(label_encoder_clean.classes_)
class_ids = np.arange(len(class_names))

y_bin_orig = label_binarize(y_true_orig, classes=class_ids)
y_bin_log = label_binarize(y_true_log, classes=class_ids)

fig, ax = plt.subplots(figsize=(10, 7))

models = [
    (y_bin_orig, probs_orig, "Original FT-Transformer", "#0077BB"),
    (y_bin_log, probs_log, "Log-Transformed FT-Transformer", "#EE7733")
]

for y_bin, probs, name, color in models:
    precision_values = []
    recall_values = []
    valid_aps = []

    for i in class_ids:
        if np.unique(y_bin[:, i]).size < 2:
            continue

        precision, recall, _ = precision_recall_curve(
            y_bin[:, i], probs[:, i]
        )

        ap = average_precision_score(y_bin[:, i], probs[:, i])
        precision_values.append(
            np.interp(np.linspace(0, 1, 501), recall[::-1], precision[::-1])
        )
        recall_values.append(ap)

    # Macro-average Average Precision across classes
    macro_ap = np.mean(recall_values)

    # Plot each class's PR curve faintly to show class-level behavior
    for i in class_ids:
        if np.unique(y_bin[:, i]).size < 2:
            continue
        p, r, _ = precision_recall_curve(y_bin[:, i], probs[:, i])
        ax.plot(r, p, color=color, alpha=0.12, linewidth=0.8)

    # Plot the macro-average curve
    mean_recall = np.linspace(0, 1, 501)
    mean_precision = np.mean(precision_values, axis=0)

    ax.plot(
        mean_recall, mean_precision,
        color=color, linewidth=2.8,
        label=f"{name} (Macro AP = {macro_ap:.4f})"
    )

ax.set_title("Precision–Recall Curves — Validation", fontsize=15, pad=15)
ax.set_xlabel("Recall", fontsize=12)
ax.set_ylabel("Precision", fontsize=12)
ax.set_xlim(0, 1)
ax.set_ylim(0, 1.02)
ax.grid(True, linestyle="--", alpha=0.3)
ax.legend(loc="lower left", fontsize=9)

plt.tight_layout()
plt.show()

import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score
)

# Calculate validation metrics
models = {
    "Original FT-Transformer": (y_val_original, pred_val_original),
    "Log-Transformed FT-Transformer": (y_val_log, pred_val_log)
}

metric_names = ["Accuracy", "Macro Precision", "Macro Recall", "Macro F1"]

scores = {}
for name, (y_true, y_pred) in models.items():
    scores[name] = [
        accuracy_score(y_true, y_pred),
        precision_score(y_true, y_pred, average="macro", zero_division=0),
        recall_score(y_true, y_pred, average="macro", zero_division=0),
        f1_score(y_true, y_pred, average="macro", zero_division=0)
    ]

# Convert scores to percentages
scores = {name: np.array(values) * 100 for name, values in scores.items()}

# Radar chart coordinates
angles = np.linspace(0, 2 * np.pi, len(metric_names), endpoint=False).tolist()
angles += angles[:1]

fig, ax = plt.subplots(figsize=(8, 8), subplot_kw={"polar": True})

colors = ["#0077BB", "#EE7733"]

for (name, values), color in zip(scores.items(), colors):
    values_closed = values.tolist() + [values[0]]
    ax.plot(
        angles, values_closed,
        color=color, linewidth=2.5, label=name
    )
    ax.fill(angles, values_closed, color=color, alpha=0.12)

ax.set_xticks(angles[:-1])
ax.set_xticklabels(metric_names, fontsize=10)
ax.set_ylim(0, 100)
ax.set_yticks([20, 40, 60, 80, 100])
ax.set_yticklabels(["20%", "40%", "60%", "80%", "100%"])
ax.set_title(
    "FT-Transformer Validation Performance",
    fontsize=14, fontweight="bold", pad=25
)
ax.legend(loc="upper right", bbox_to_anchor=(1.35, 1.12), fontsize=9)
ax.grid(alpha=0.35)

plt.tight_layout()
plt.show()

print("Validation metrics:")
for name, values in scores.items():
    print(f"\n{name}")
    for metric, value in zip(metric_names, values):
        print(f"{metric}: {value:.2f}%")

