import numpy as np
import matplotlib.pyplot as plt

# Identify Normal and Fuzzers classes
class_names = list(label_encoder_clean.classes_)
normal_id = class_names.index("Normal")
fuzzers_id = class_names.index("Fuzzers")

def calculate_false_alarm_metrics(y_true, y_pred):
    actual_normal = (y_true == normal_id)
    total_normal = actual_normal.sum()

    false_alarms = actual_normal & (y_pred != normal_id)
    normal_to_fuzzers = actual_normal & (y_pred == fuzzers_id)

    far = 100 * false_alarms.sum() / max(total_normal, 1)
    normal_fuzzers = 100 * normal_to_fuzzers.sum() / max(total_normal, 1)

    return far, normal_fuzzers

original_far, original_nf = calculate_false_alarm_metrics(
    y_val_original, pred_val_original
)

log_far, log_nf = calculate_false_alarm_metrics(
    y_val_log, pred_val_log
)

# Plot percentages
labels = ["All Normal false alarms", "Normal → Fuzzers"]
original_values = [original_far, original_nf]
log_values = [log_far, log_nf]

y = np.arange(len(labels))
height = 0.32

fig, ax = plt.subplots(figsize=(10, 5.5))

bars1 = ax.barh(
    y - height / 2, original_values, height,
    label="Original FT-Transformer",
    color="#4477AA"
)

bars2 = ax.barh(
    y + height / 2, log_values, height,
    label="Log-Transformed FT-Transformer",
    color="#EE6677"
)

ax.bar_label(bars1, fmt="%.2f%%", padding=5, fontsize=10)
ax.bar_label(bars2, fmt="%.2f%%", padding=5, fontsize=10)

ax.set_yticks(y)
ax.set_yticklabels(labels, fontsize=11)
ax.set_xlabel("False-alarm rate (%)", fontsize=12)
ax.set_title(
    "Normal Traffic False-Alarm Comparison — Validation",
    fontsize=14, fontweight="bold", pad=15
)

ax.set_xlim(0, max(original_values + log_values) * 1.3)
ax.grid(axis="x", linestyle="--", alpha=0.3)
ax.set_axisbelow(True)
ax.legend(frameon=False)
ax.invert_yaxis()

plt.tight_layout()
plt.show()

print(f"Original Normal FAR: {original_far:.2f}%")
print(f"Log-transformed Normal FAR: {log_far:.2f}%")
print(f"Original Normal → Fuzzers: {original_nf:.2f}%")
print(f"Log-transformed Normal → Fuzzers: {log_nf:.2f}%")

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

from sklearn.metrics import f1_score, recall_score

# Use probabilities from the log-transformed model
class_names = list(label_encoder_clean.classes_)
normal_id = class_names.index("Normal")
attack_ids = [i for i, name in enumerate(class_names) if name != "Normal"]

# probs_log and y_val_log come from our validation evaluation
actual_normal = (y_val_log == normal_id)
actual_attack = ~actual_normal

def predict_with_normal_threshold(probabilities, threshold):
    # If Normal probability passes threshold, predict Normal.
    # Otherwise, choose the most likely attack class.
    attack_probs = probabilities[:, attack_ids]
    best_attack_ids = np.array(attack_ids)[attack_probs.argmax(axis=1)]

    predictions = best_attack_ids.copy()
    predictions[probabilities[:, normal_id] >= threshold] = normal_id
    return predictions

results = []

for threshold in np.arange(0.10, 0.96, 0.05):
    predictions = predict_with_normal_threshold(probs_log, threshold)

    far = np.mean(predictions[actual_normal] != normal_id) * 100
    attack_recall = np.mean(predictions[actual_attack] != normal_id) * 100

    macro_attack_recall = recall_score(
        y_val_log[actual_attack],
        predictions[actual_attack],
        labels=attack_ids,
        average="macro",
        zero_division=0
    ) * 100

    macro_f1 = f1_score(
        y_val_log, predictions,
        labels=list(range(len(class_names))),
        average="macro",
        zero_division=0
    ) * 100

    results.append({
        "Normal_threshold": threshold,
        "Normal_FAR_%": far,
        "Attack_detection_recall_%": attack_recall,
        "Macro_attack_recall_%": macro_attack_recall,
        "Overall_macro_F1_%": macro_f1
    })

results_df = pd.DataFrame(results)

print("Validation threshold experiment:")
print(results_df.round(2).to_string(index=False))

# Plot FAR and attack recall against threshold
fig, ax = plt.subplots(figsize=(10, 6))

ax.plot(
    results_df["Normal_threshold"],
    results_df["Normal_FAR_%"],
    marker="o", linewidth=2.5,
    color="#D55E00", label="Normal FAR"
)

ax.plot(
    results_df["Normal_threshold"],
    results_df["Attack_detection_recall_%"],
    marker="s", linewidth=2.5,
    color="#0072B2", label="Attack detection recall"
)

ax.set_xlabel("Normal-class threshold")
ax.set_ylabel("Rate (%)")
ax.set_title("Threshold Tuning: False Alarms vs Attack Detection")
ax.set_ylim(0, 105)
ax.grid(True, linestyle="--", alpha=0.3)
ax.legend()
plt.tight_layout()
plt.show()

import numpy as np
import pandas as pd
from sklearn.metrics import f1_score, recall_score

class_names = list(label_encoder_clean.classes_)
normal_id = class_names.index("Normal")
attack_ids = [i for i, name in enumerate(class_names) if name != "Normal"]

actual_normal = (y_val_log == normal_id)
actual_attack = ~actual_normal

results_fine = []

for threshold in np.round(np.arange(0.02, 0.301, 0.02), 2):
    predictions = predict_with_normal_threshold(probs_log, threshold)

    normal_far = np.mean(
        predictions[actual_normal] != normal_id
    ) * 100

    attack_detection = np.mean(
        predictions[actual_attack] != normal_id
    ) * 100

    macro_attack_recall = recall_score(
        y_val_log[actual_attack],
        predictions[actual_attack],
        labels=attack_ids,
        average="macro",
        zero_division=0
    ) * 100

    macro_f1 = f1_score(
        y_val_log,
        predictions,
        labels=list(range(len(class_names))),
        average="macro",
        zero_division=0
    ) * 100

    results_fine.append({
        "Threshold": threshold,
        "Normal_FAR_%": normal_far,
        "Attack_detection_recall_%": attack_detection,
        "Macro_attack_recall_%": macro_attack_recall,
        "Macro_F1_%": macro_f1
    })

fine_df = pd.DataFrame(results_fine)

print(fine_df.round(2).to_string(index=False))

