import copy
import numpy as np
import torch
import torch.nn as nn
from sklearn.metrics import f1_score, accuracy_score

# Keep the existing models unchanged
ft_focal = FTTransformerClass().to(device)

# Focal Loss
class FocalLoss(nn.Module):
    def __init__(self, alpha=None, gamma=2.0):
        super().__init__()
        self.alpha = alpha
        self.gamma = gamma

    def forward(self, logits, targets):
        ce = nn.functional.cross_entropy(
            logits, targets, reduction="none"
        )
        pt = torch.exp(-ce)
        loss = (1 - pt) ** self.gamma * ce

        if self.alpha is not None:
            alpha = self.alpha.to(logits.device)
            loss = alpha[targets] * loss

        return loss.mean()

# Use the existing square-root class weights
alpha_focal = torch.as_tensor(
    np.asarray(class_weights_clean),
    dtype=torch.float32,
    device=device
)

criterion_focal = FocalLoss(alpha=alpha_focal, gamma=2.0)
optimizer_focal = torch.optim.AdamW(
    ft_focal.parameters(),
    lr=0.0005,
    weight_decay=1e-4
)

best_focal_f1 = -1
best_focal_state = None
patience = 4
wait = 0
max_epochs = 20

for epoch in range(max_epochs):
    ft_focal.train()
    running_loss = 0.0
    total = 0

    for xn, xc, y in train_loader_log:
        xn = xn.to(device)
        xc = xc.to(device)
        y = y.to(device).long()

        optimizer_focal.zero_grad()
        logits = ft_focal(xn, xc)
        loss = criterion_focal(logits, y)
        loss.backward()

        torch.nn.utils.clip_grad_norm_(
            ft_focal.parameters(), max_norm=1.0
        )
        optimizer_focal.step()

        running_loss += loss.item() * y.size(0)
        total += y.size(0)

    # Validate after each epoch
    ft_focal.eval()
    val_true, val_pred = [], []

    with torch.no_grad():
        for xn, xc, y in val_loader_log:
            logits = ft_focal(xn.to(device), xc.to(device))
            pred = logits.argmax(dim=1).cpu().numpy()

            val_true.extend(y.numpy())
            val_pred.extend(pred)

    val_macro_f1 = f1_score(
        val_true,
        val_pred,
        labels=list(range(len(label_encoder_clean.classes_))),
        average="macro",
        zero_division=0
    )
    val_accuracy = accuracy_score(val_true, val_pred)

    print(
        f"Epoch {epoch+1:02d}/{max_epochs} | "
        f"Loss: {running_loss/max(total,1):.4f} | "
        f"Val Accuracy: {val_accuracy:.4f} | "
        f"Val Macro-F1: {val_macro_f1:.4f}"
    )

    if val_macro_f1 > best_focal_f1:
        best_focal_f1 = val_macro_f1
        best_focal_state = copy.deepcopy(ft_focal.state_dict())
        best_focal_epoch = epoch + 1
        wait = 0
    else:
        wait += 1

    if wait >= patience:
        print("Early stopping.")
        break

ft_focal.load_state_dict(best_focal_state)

print("\nFocal Loss training complete.")
print("Best epoch:", best_focal_epoch)
print(f"Best validation Macro-F1: {best_focal_f1:.4f}")
print("Log-transform baseline Macro-F1: 0.6038")

