import numpy as np
import pandas as pd
import torch
from sklearn.metrics import recall_score

def get_validation_predictions(model, loader):
    model.eval()
    y_true, y_pred = [], []

    with torch.no_grad():
        for xn, xc, y in loader:
            logits = model(xn.to(device), xc.to(device))
            y_pred.extend(logits.argmax(dim=1).cpu().numpy())
            y_true.extend(y.numpy())

    return np.asarray(y_true), np.asarray(y_pred)

y_true, pred_log = get_validation_predictions(
    ft_log, val_loader_log
)
_, pred_targeted = get_validation_predictions(
    ft_targeted, val_loader_log
)
_, pred_focal = get_validation_predictions(
    ft_focal, val_loader_log
)

class_names = list(label_encoder_clean.classes_)

comparison = []

for class_id, name in enumerate(class_names):
    row = {"Class": name}

    for model_name, predictions in [
        ("Log_transform", pred_log),
        ("Targeted_weights", pred_targeted),
        ("Focal_Loss", pred_focal)
    ]:
        mask = y_true == class_id
        recall = (
            np.mean(predictions[mask] == class_id) * 100
            if mask.any() else np.nan
        )
        row[model_name + "_Recall_%"] = recall

    comparison.append(row)

comparison_df = pd.DataFrame(comparison)
print(comparison_df.round(2).to_string(index=False))

import numpy as np
import pandas as pd
from torch.utils.data import WeightedRandomSampler

# Get the encoded training labels from the existing training loader.
# The labels are the third TensorDataset item.
train_labels_for_sampler = np.concatenate([
    y.numpy() for _, _, y in train_loader_log
])

class_names = list(label_encoder_clean.classes_)
class_counts = np.bincount(
    train_labels_for_sampler,
    minlength=len(class_names)
)

# Moderate sampling: inverse square-root frequency.
# Rare classes are sampled more often, but less aggressively
# than with full inverse-frequency sampling.
sample_weights = (
    1.0 / np.sqrt(np.maximum(class_counts, 1))
)[train_labels_for_sampler]

sampler = WeightedRandomSampler(
    weights=sample_weights,
    num_samples=len(train_labels_for_sampler),
    replacement=True
)

# Estimate the resulting class mix
sampled_indices = list(iter(sampler))
sampled_labels = train_labels_for_sampler[sampled_indices]
sampled_counts = np.bincount(
    sampled_labels,
    minlength=len(class_names)
)

sampler_summary = pd.DataFrame({
    "Class": class_names,
    "Original_count": class_counts,
    "Expected_sampled_count": sampled_counts
})

print(sampler_summary.to_string(index=False))

import copy
import numpy as np
import torch
import torch.nn as nn
from torch.utils.data import DataLoader, WeightedRandomSampler, TensorDataset
from sklearn.metrics import f1_score, accuracy_score

# Recover the tensors already used by the log-transformed pipeline
train_dataset_log = train_loader_log.dataset

train_labels_sampler = train_dataset_log.tensors[2].cpu().numpy()
counts_sampler = np.bincount(
    train_labels_sampler,
    minlength=len(label_encoder_clean.classes_)
)

# Moderate inverse-square-root sampling
per_class_weights = 1.0 / np.sqrt(np.maximum(counts_sampler, 1))
per_sample_weights = per_class_weights[train_labels_sampler]

sampler_train = WeightedRandomSampler(
    weights=torch.as_tensor(per_sample_weights, dtype=torch.double),
    num_samples=len(train_labels_sampler),
    replacement=True
)

train_loader_sampler = DataLoader(
    train_dataset_log,
    batch_size=512,
    sampler=sampler_train
)

# Separate model; existing models remain unchanged
ft_sampler = FTTransformerClass().to(device)

# No class weights in this loss: sampling is the only intervention
criterion_sampler = nn.CrossEntropyLoss()

optimizer_sampler = torch.optim.AdamW(
    ft_sampler.parameters(),
    lr=0.0005,
    weight_decay=1e-4
)

best_sampler_f1 = -1
best_sampler_state = None
patience = 4
wait = 0

for epoch in range(20):
    ft_sampler.train()
    total_loss = 0.0
    total_n = 0

    for xn, xc, y in train_loader_sampler:
        xn = xn.to(device)
        xc = xc.to(device)
        y = y.to(device).long()

        optimizer_sampler.zero_grad()
        logits = ft_sampler(xn, xc)
        loss = criterion_sampler(logits, y)
        loss.backward()

        torch.nn.utils.clip_grad_norm_(
            ft_sampler.parameters(), max_norm=1.0
        )
        optimizer_sampler.step()

        total_loss += loss.item() * y.size(0)
        total_n += y.size(0)

    ft_sampler.eval()
    y_true_sampler, y_pred_sampler = [], []

    with torch.no_grad():
        for xn, xc, y in val_loader_log:
            logits = ft_sampler(xn.to(device), xc.to(device))
            y_pred_sampler.extend(
                logits.argmax(dim=1).cpu().numpy()
            )
            y_true_sampler.extend(y.numpy())

    val_f1_sampler = f1_score(
        y_true_sampler,
        y_pred_sampler,
        labels=list(range(len(label_encoder_clean.classes_))),
        average="macro",
        zero_division=0
    )
    val_acc_sampler = accuracy_score(
        y_true_sampler, y_pred_sampler
    )

    print(
        f"Epoch {epoch+1:02d}/20 | "
        f"Loss: {total_loss/max(total_n,1):.4f} | "
        f"Val Accuracy: {val_acc_sampler:.4f} | "
        f"Val Macro-F1: {val_f1_sampler:.4f}"
    )

    if val_f1_sampler > best_sampler_f1:
        best_sampler_f1 = val_f1_sampler
        best_sampler_state = copy.deepcopy(
            ft_sampler.state_dict()
        )
        best_sampler_epoch = epoch + 1
        wait = 0
    else:
        wait += 1

    if wait >= patience:
        print("Early stopping.")
        break

ft_sampler.load_state_dict(best_sampler_state)

print("\nSampler experiment complete.")
print("Best epoch:", best_sampler_epoch)
print(f"Best validation Macro-F1: {best_sampler_f1:.4f}")
print("Current leading baseline: 0.6038")

