# ============================================================
# AI-IDS: TARGETED FT-TRANSFORMER EXPERIMENT
# Goal: Reduce Exploits <-> DoS classification confusion
# Reference model: ft_log (validation macro-F1 = 0.6038)
# ============================================================

import copy
import numpy as np
import torch
import torch.nn as nn
from sklearn.metrics import (
    f1_score,
    accuracy_score,
    classification_report,
    confusion_matrix
)

# ----------------------------
# 1. Check existing variables
# ----------------------------
required_vars = [
    "ft_log", "train_loader_log", "val_loader_log",
    "class_weights_clean", "label_encoder_clean", "device"
]

missing = [name for name in required_vars if name not in globals()]

if missing:
    raise NameError(
        f"Missing variables: {missing}. "
        "Run the earlier data-preparation and ft_log training cells first."
    )

class_names = list(label_encoder_clean.classes_)
EXPLOITS_ID = class_names.index("Exploits")
DOS_ID = class_names.index("DoS")

print("Device:", device)
print("Exploits class ID:", EXPLOITS_ID)
print("DoS class ID:", DOS_ID)

# ----------------------------
# 2. Copy the current best model
# ----------------------------
# ft_log remains unchanged
ft_pair = copy.deepcopy(ft_log).to(device)

# Convert NumPy OR tensor weights safely
weights_pair = torch.as_tensor(
    class_weights_clean,
    dtype=torch.float32,
    device=device
)

criterion_pair = nn.CrossEntropyLoss(weight=weights_pair)

optimizer_pair = torch.optim.AdamW(
    ft_pair.parameters(),
    lr=0.0003,
    weight_decay=1e-4
)

# Moderate penalty for confusing the two classes
PAIR_PENALTY = 0.15
MARGIN = 0.20
MAX_EPOCHS = 8
PATIENCE = 3

best_pair_f1 = -1.0
best_pair_state = None
wait_pair = 0

# ----------------------------
# 3. Train the experimental model
# ----------------------------
for epoch in range(1, MAX_EPOCHS + 1):

    ft_pair.train()
    running_loss = 0.0

    for xn, xc, y in train_loader_log:
        xn = xn.to(device)
        xc = xc.to(device)
        y = y.to(device).long()

        optimizer_pair.zero_grad()

        logits = ft_pair(xn, xc)
        loss = criterion_pair(logits, y)

        # Penalize Exploits examples ranked below DoS
        exploits_mask = (y == EXPLOITS_ID)

        if exploits_mask.any():
            exploits_margin_loss = torch.relu(
                MARGIN - (
                    logits[exploits_mask, EXPLOITS_ID]
                    - logits[exploits_mask, DOS_ID]
                )
            ).mean()

            loss = loss + PAIR_PENALTY * exploits_margin_loss

        # Penalize DoS examples ranked below Exploits
        dos_mask = (y == DOS_ID)

        if dos_mask.any():
            dos_margin_loss = torch.relu(
                MARGIN - (
                    logits[dos_mask, DOS_ID]
                    - logits[dos_mask, EXPLOITS_ID]
                )
            ).mean()

            loss = loss + PAIR_PENALTY * dos_margin_loss

        loss.backward()

        torch.nn.utils.clip_grad_norm_(
            ft_pair.parameters(),
            max_norm=1.0
        )

        optimizer_pair.step()
        running_loss += loss.item()

    # ----------------------------
    # 4. Validate after each epoch
    # ----------------------------
    ft_pair.eval()
    y_true_pair = []
    y_pred_pair = []

    with torch.no_grad():
        for xn, xc, y in val_loader_log:
            xn = xn.to(device)
            xc = xc.to(device)

            logits = ft_pair(xn, xc)
            predictions = logits.argmax(dim=1).cpu().numpy()

            y_pred_pair.extend(predictions)
            y_true_pair.extend(y.cpu().numpy())

    val_macro_f1 = f1_score(
        y_true_pair,
        y_pred_pair,
        average="macro",
        zero_division=0
    )

    val_accuracy = accuracy_score(
        y_true_pair,
        y_pred_pair
    )

    avg_loss = running_loss / len(train_loader_log)

    print(
        f"Epoch {epoch:02d}/{MAX_EPOCHS} | "
        f"Loss: {avg_loss:.4f} | "
        f"Val Accuracy: {val_accuracy:.4f} | "
        f"Val Macro-F1: {val_macro_f1:.4f}"
    )

    # Keep the checkpoint with the highest validation macro-F1
    if val_macro_f1 > best_pair_f1:
        best_pair_f1 = val_macro_f1
        best_pair_state = copy.deepcopy(ft_pair.state_dict())
        wait_pair = 0
    else:
        wait_pair += 1

    if wait_pair >= PATIENCE:
        print("Early stopping: validation macro-F1 did not improve.")
        break

# Restore best experimental checkpoint
if best_pair_state is not None:
    ft_pair.load_state_dict(best_pair_state)

# ----------------------------
# 5. Final validation report
# ----------------------------
ft_pair.eval()
y_true_pair = []
y_pred_pair = []

with torch.no_grad():
    for xn, xc, y in val_loader_log:
        logits = ft_pair(xn.to(device), xc.to(device))
        y_pred_pair.extend(
            logits.argmax(dim=1).cpu().numpy()
        )
        y_true_pair.extend(y.cpu().numpy())

pair_accuracy = accuracy_score(y_true_pair, y_pred_pair)
pair_macro_f1 = f1_score(
    y_true_pair, y_pred_pair,
    average="macro", zero_division=0
)

print("\n" + "=" * 60)
print("TARGETED EXPERIMENT — VALIDATION RESULTS")
print("=" * 60)
print(f"Accuracy:          {pair_accuracy:.4f}")
print(f"Macro-F1:          {pair_macro_f1:.4f}")
print(f"Reference ft_log:  0.6038 macro-F1")
print(f"Difference:        {(pair_macro_f1 - 0.6038):+.4f}")

print("\nClass-wise classification report:")
print(
    classification_report(
        y_true_pair,
        y_pred_pair,
        labels=list(range(len(class_names))),
        target_names=class_names,
        digits=4,
        zero_division=0
    )
)

# ----------------------------
# 6. Measure Exploits -> DoS confusion
# ----------------------------
cm_pair = confusion_matrix(
    y_true_pair,
    y_pred_pair,
    labels=list(range(len(class_names)))
)

exploits_to_dos = cm_pair[EXPLOITS_ID, DOS_ID]
dos_to_exploits = cm_pair[DOS_ID, EXPLOITS_ID]

print("Exploits predicted as DoS:", exploits_to_dos)
print("DoS predicted as Exploits:", dos_to_exploits)

# ----------------------------
# 7. Measure Normal false-alarm rate
# ----------------------------
NORMAL_ID = class_names.index("Normal")
normal_rows = np.array(y_true_pair) == NORMAL_ID

normal_count = int(normal_rows.sum())
false_alarms = int(
    (np.array(y_pred_pair)[normal_rows] != NORMAL_ID).sum()
)

normal_far = (
    false_alarms / normal_count
    if normal_count > 0 else float("nan")
)

print(f"\nActual Normal validation samples: {normal_count}")
print(f"False alarms:                     {false_alarms}")
print(f"Normal FAR:                       {normal_far:.4%}")

print("\nReference model ft_log is unchanged.")
print("Keep ft_pair only if the validation results justify it.")

