import numpy as np
import pandas as pd
from sklearn.metrics import classification_report

def get_class_report(model, loader):
    model.eval()
    actuals, predictions = [], []

    with torch.no_grad():
        for xn, xc, y in loader:
            logits = model(xn.to(device), xc.to(device))
            predictions.extend(
                logits.argmax(dim=1).cpu().numpy()
            )
            actuals.extend(y.cpu().numpy())

    report = classification_report(
        actuals,
        predictions,
        labels=list(range(len(class_names))),
        target_names=class_names,
        output_dict=True,
        zero_division=0
    )

    return pd.DataFrame({
        "Precision (%)": [
            report[c]["precision"] * 100 for c in class_names
        ],
        "Recall (%)": [
            report[c]["recall"] * 100 for c in class_names
        ],
        "F1 (%)": [
            report[c]["f1-score"] * 100 for c in class_names
        ]
    }, index=class_names)

baseline_report = get_class_report(ft_log, val_loader_log)
targeted_report = get_class_report(ft_pair, val_loader_log)

print("=== FT-Transformer baseline ===")
print(baseline_report.round(2).to_string())

print("\n=== Targeted penalty experiment ===")
print(targeted_report.round(2).to_string())

print("\n=== Change in F1 (targeted minus baseline), percentage points ===")
f1_change = targeted_report["F1 (%)"] - baseline_report["F1 (%)"]
print(f1_change.round(2).to_string())

