actual_normal = (val_y_actual == normal_index)
predicted_normal = (val_predictions == normal_index)

# Normal incorrectly predicted as an attack
fp_normal = np.sum(~actual_normal & predicted_normal)

# Attacks incorrectly predicted as Normal
fn_normal = np.sum(actual_normal & ~predicted_normal)

# Correctly identified attacks (for Normal-vs-attack view)
tn_normal = np.sum(~actual_normal & ~predicted_normal)

fpr_normal = (
    fp_normal / (fp_normal + tn_normal)
    if (fp_normal + tn_normal) > 0 else 0.0
)

