# Shift categories to non-negative indices; reserve 0 for unknown values
X_train_cat_clean += 1
X_val_cat_clean += 1

# Encode target labels consistently
target_encoder_clean = LabelEncoder()
y_train_clean = target_encoder_clean.fit_transform(y_train_raw)
y_val_clean = target_encoder_clean.transform(y_val_raw)

